                mechanics = new[] { "TURRET", "LASER_FENCE", "INTERACT" },
                boss = "Razorback", bossBody = "HP 120 RH. Phase 1 (100-60%): chain pounce, two red arrows shown one after the other (0.6 s apart) so you dodge twice; if a pounce ends in a crate stack it breaks the crates and is stunned 2.5 s (take +50% damage). Phase 2 (60-25%): calls 2 Leapers every 12 s and pounces three times in a chain; the fences start cycling, and a pounce that crosses a live fence stuns it 3 s and burns 8 RH. Phase 3 (25-0%): enraged, arrows lock 0.3 s sooner and it tail-swipes (120 degree cone, 0.6 s red flash, 20 HP) after every landing. Captured turrets always target it.", bossLook = "Leaper model at 2.2x, crimson #8f1d1d body with a bone-white crest #e8e0d0 (emissive edge), red eye glow; screech pitched down 30%.",
                modifiers = new[] { "Power Surge: fences cycle twice as fast.", "Abandoned Armoury: turrets fire 50% faster but last only 15 s.", "Sealed Tight: doors need a hack even after the room is cleared (2.5 s).", "Tick Infestation: every Drone group brings 3 Ticks." },
                stars = new[] { "Clear the zone.", "No revive and under par (3:00).", "Finish both ESCAPE floors in under 90 s each." }, starBonus = "Clear with every turret in the zone captured at least once.", par = 180,
                layoutNotes = new Dictionary<string, string> { {"evac-a", "Four-room loop: start room top-left, door right, door down, door left into the lift room. The turret sits in room 2."}, {"evac-b", "Shuttle pad. Fuel pump G in a striped box, fence pairs cutting the top and bottom spawn lanes, four corner turrets."}, {"evac-c", "Fence Run. Three rooms left to right; the middle one is a laser-fence maze."}, {"evac-boss", "Shuttle Bay. Open bay with crate stacks as pounce bait, two turrets, four fence posts in the middle."} } },
            new SectorDef { id = "kessler-refinery", name = "KESSLER REFINERY", num = 3, act = "I", power = 1100, tier = 1, art = "kessler", lat = 41.3f, lon = 112.0f, endless = false,
                blurb = "A slag refinery still running on autopilot", pitch = "A slag refinery still running on autopilot: conveyor belts carry you and the swarm toward molten channels and hydraulic presses.", signature = "The floor moves. Belts give you free speed one way and make you fight to go the other, and they carry the swarm the same way, so a belt that ends in slag is a kill lane: stand beyond it and let the auto-fire shove pack slide in. Presses slam on the striped cells on a fixed beat (STRIKE fixed mode: a circle on every 'y' cell, every 4 s), so crossing a belt is a timing puzzle. The swarm's flow field avoids slag, so it funnels through predictable crossings you can hold.",
                unlockAny = new string[] { "evac-deck" }, unlockAfter = "evac-deck",
                floorTint = C(0x3b3f45), wallTint = C(0x6b4a33), accent = C(0x7d8288), sun = C(0xffd8b0), sunIntensity = 0.7f, ambient = C(0xa0a8b8), fog = C(0x3a2a20), fogStart = 18.0f, fogEnd = 50.0f, particles = Particles.Embers,
                order = new[] { Game.Goal.Purge, Game.Goal.Hold, Game.Goal.Hunt, Game.Goal.Survive, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Purge, spec = "PURGE", param = "3 waves", layout = "kessler-refinery/kess-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 38), new EnemyEntry("Spitter", 3), new EnemyEntry("Tick", 6) }, events = "Teaches the kill lane: the north-running belt on the left feeds straight into the slag channel. Wave 2 spawns right on that belt.", script = "[{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"fixed\",\"cells\":\"y\",\"interval\":4,\"alternate\":\"halves\",\"radius\":1,\"delay\":1.5,\"skin\":\"press\"}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Belts that end in slag are kill lanes. Let them carry the swarm in.\"}},{\"when\":{\"wave\":{\"n\":2,\"at\":\"start\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Drone\",\"count\":12,\"at\":\"^\",\"group\":\"pack\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Hold, spec = "HOLD", param = "30 s", layout = "kessler-refinery/kess-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 36), new EnemyEntry("Leaper", 4), new EnemyEntry("Carapace", 1) }, events = "The ring sits inside a conveyor loop, so the swarm is carried around you; leaving and re-entering costs a belt crossing. Vents on both flanks pulse steam (VENT, steam skin).", script = "[{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"VENT\",\"skin\":\"steam\"}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"The loop carries the swarm around you. Crossing the belt costs time.\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Hunt, spec = "HUNT", param = "3 nests", layout = "kessler-refinery/kess-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 40), new EnemyEntry("Leaper", 4), new EnemyEntry("Spitter", 4), new EnemyEntry("Shrieker", 1) }, events = "Nests sit on islands cut off by slag; one-way belts are the bridges, so each nest is a commitment. A Shrieker guards the last nest.", script = "[{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"fixed\",\"cells\":\"y\",\"interval\":4,\"alternate\":\"halves\",\"radius\":1,\"delay\":1.5,\"skin\":\"press\"}},{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"VENT\",\"skin\":\"steam\"}},{\"when\":{\"done\":{\"kind\":\"nest\",\"count\":2}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Shrieker\",\"count\":1,\"at\":\"n\",\"group\":\"pack\"}},{\"when\":{\"done\":{\"kind\":\"nest\",\"index\":1}},\"do\":\"SET\",\"params\":{\"system\":\"VENT\",\"cycle\":4}},{\"when\":{\"done\":{\"kind\":\"nest\",\"index\":2}},\"do\":\"SET\",\"params\":{\"system\":\"VENT\",\"cycle\":3}},{\"when\":{\"done\":{\"kind\":\"nest\"}},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":4,\"radius\":2,\"interval\":6,\"skin\":\"glob\",\"aim\":\"*\"}},{\"when\":{\"done\":{\"kind\":\"nest\"}},\"do\":\"HINT\",\"params\":{\"text\":\"THE REFINERY IS OVERHEATING\"}},{\"when\":{\"done\":{\"kind\":\"nest\"}},\"do\":\"CUE\",\"params\":{\"id\":\"slag_surge\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Survive, spec = "SURVIVE", param = "45 s, 'Reversal'", layout = "kessler-refinery/kess-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 52), new EnemyEntry("Leaper", 5), new EnemyEntry("Carapace", 2), new EnemyEntry("Bloater", 1), new EnemyEntry("Tick", 8) }, events = "Every 12 s every belt reverses (chevrons flash 1.5 s first). The kill lane flips into a launch lane that throws enemies at you.", script = "[{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"fixed\",\"cells\":\"y\",\"interval\":4,\"alternate\":\"halves\",\"radius\":1,\"delay\":1.5,\"skin\":\"press\"}},{\"when\":{\"every\":{\"s\":12}},\"do\":\"TOGGLE\",\"params\":{\"system\":\"CONVEYOR\",\"state\":\"reverse\",\"warn\":1.5}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "kessler-refinery/kess-boss", enemies = new EnemyEntry[] { new EnemyEntry("Slagback", 1), new EnemyEntry("Drone", 18), new EnemyEntry("Carapace", 2) }, events = "Smelting floor: four slag pools, two press rows. The boss can be dunked.", script = "[{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"fixed\",\"cells\":\"y\",\"interval\":4,\"alternate\":\"halves\",\"radius\":1,\"delay\":1.5,\"skin\":\"press\"}},{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"VENT\",\"skin\":\"steam\"}},{\"when\":{\"boss_hp\":0.6},\"do\":\"STRIKE\",\"params\":{\"mode\":\"fixed\",\"cells\":\"y\",\"interval\":2,\"alternate\":\"halves\",\"radius\":1,\"delay\":1.0,\"skin\":\"press\"}}]" },
                },
                mechanics = new[] { "CONVEYOR", "SLAG", "VENT", "STRIKE", "NEST" },
                boss = "Slagback", bossBody = "HP 160 RH, armoured front (15% damage, as the Carapace). Phase 1: Carapace charge (yellow lane, 0.9 s windup) twice per cycle; baiting it into a slag pool deals 15% of its max HP, ignites it for 4 s and strips its front armour for 6 s (glowing white). Phase 2 (60%): it trails molten slag (SPREAD fire skin on its path, 6 s life) and the presses double speed. Phase 3 (25%): it slams the floor, lifting 3 random STRIKE circles around you on every charge recovery. A charge through a press cell while the press falls stuns it 3 s.", bossLook = "Carapace look (Bloater model 0.75x squashed) at 2.4x scale, black #1d1d1f shell with glowing orange cracks #ff6a1a (emissive), ember particles; sparks when bullets hit the front.",
                modifiers = new[] { "Overdrive: belts run at 5 m/s.", "Heat Wave: slag channels widen by one cell on floors 3-5.", "Rolling Stock: barrels ride the belts and explode on contact.", "Press Gang: presses on every belt, every 3 s." },
                stars = new[] { "Clear the zone.", "No revive and under par (4:00).", "Dunk Slagback in slag three times." }, starBonus = "Kill 40 enemies with slag, presses or belts in one run.", par = 240,
                layoutNotes = new Dictionary<string, string> { {"kess-a", "Belt Hall. A slag channel splits the hall; a south-running belt is the main bridge, a north belt on the left is the kill lane."}, {"kess-b", "Loop Control. HOLD ring inside a conveyor loop, slag at the bottom corners."}, {"kess-c", "Slag Islands. Three nests on islands separated by slag; one-way belts and two narrow bridges connect them."}, {"kess-boss", "Smelting Floor. Four slag pools, two press rows on the striped cells, vents on the sides."} } },
            new SectorDef { id = "verdant-colony", name = "VERDANT COLONY", num = 4, act = "I", power = 1200, tier = 1, art = "verdant", lat = 34.5f, lon = -110.5f, endless = false,
                blurb = "A farming dome gone feral", pitch = "A farming dome gone feral: hedgerows you can shoot over but not walk through, spore pods that hide the swarm, and the first hive creep crawling between the crops.", signature = "Crop hedges ('r', green) block walking but not bullets, so you fight across rows and the swarm has to go around them, which strings packs out into lines. Spore clouds hide whole packs: you learn to shoot pods before you walk past them. Creep appears for the first time and the BURN objective teaches that dashing through creep scorches it.",
                unlockAny = new string[] { "evac-deck" }, unlockAfter = "evac-deck",
                floorTint = C(0x4a3b2a), wallTint = C(0xdfe8dc), accent = C(0x3f5a3a), sun = C(0xffe6a8), sunIntensity = 1.2f, ambient = C(0x9fbf7a), fog = C(0xb8d49a), fogStart = 6.0f, fogEnd = 100.0f, particles = Particles.Spores,
                order = new[] { Game.Goal.Purge, Game.Goal.Burn, Game.Goal.Hunt, Game.Goal.Survive, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Purge, spec = "PURGE", param = "3 waves", layout = "verdant-colony/verd-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 40), new EnemyEntry("Spitter", 4), new EnemyEntry("Tick", 6) }, events = "Spitters lob over the hedgerows. Four spore pods along the paths puff on their 15 s beat.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Shoot spore pods before you walk past them\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Burn, spec = "BURN", param = "80% of creep", layout = "verdant-colony/verd-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 38), new EnemyEntry("Leaper", 3), new EnemyEntry("Spore Pod", 4) }, events = "A creep bloom covers the greenhouse; two nests feed it. Hint on floor start: 'Dash through creep to burn it'. Killing a nest makes its creep recede, which is the efficient route.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Dash through creep to burn it\"}},{\"when\":{\"done\":{\"kind\":\"nest\",\"count\":1}},\"do\":\"HINT\",\"params\":{\"text\":\"Nest down: its creep recedes. Kill the other one.\"}},{\"when\":{\"done\":{\"kind\":\"nest\",\"index\":1}},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":3,\"radius\":2,\"interval\":2,\"skin\":\"fire\",\"aim\":\"c\",\"leaves\":\"scorch\",\"for\":12}},{\"when\":{\"done\":{\"kind\":\"nest\",\"index\":1}},\"do\":\"HINT\",\"params\":{\"text\":\"WILDFIRE: THREAD THE EMBERS\"}},{\"when\":{\"done\":{\"kind\":\"nest\",\"index\":1}},\"do\":\"CUE\",\"params\":{\"id\":\"wildfire\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Hunt, spec = "HUNT", param = "3 nests", layout = "verdant-colony/verd-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 44), new EnemyEntry("Leaper", 4), new EnemyEntry("Spitter", 4), new EnemyEntry("Carapace", 1) }, events = "Each nest is ringed by egg clusters that hatch when you get close (EGGS).", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Eggs ring every nest. Shoot them before you close in.\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Survive, spec = "SURVIVE", param = "45 s, 'Bloom'", layout = "verdant-colony/verd-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 56), new EnemyEntry("Leaper", 5), new EnemyEntry("Spitter", 5), new EnemyEntry("Bloater", 1), new EnemyEntry("Shrieker", 1) }, events = "Bloom: every pod on the floor puffs at the same moment every 15 s, blanking the map for 8 s; the Shrieker hides inside the clouds.", script = "[{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"SPORE_POD\",\"period\":15,\"sync\":true,\"cloud_s\":8}},{\"when\":{\"t\":15},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Shrieker\",\"count\":1,\"at\":\"far_S\",\"group\":\"pack\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "verdant-colony/verd-boss", enemies = new EnemyEntry[] { new EnemyEntry("Mother Bloom", 1), new EnemyEntry("Drone", 20), new EnemyEntry("Spore Pod", 6) }, events = "Central garden. The boss plants pods as it walks.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Burn her creep trail: she heals while standing on it.\"}},{\"when\":{\"boss_hp\":0.3},\"do\":\"HATCH_ALL\",\"params\":{\"wobble\":3}}]" },
                },
                mechanics = new[] { "SPORE_POD", "SPREAD", "EGGS", "NEST" },
                boss = "Mother Bloom", bossBody = "HP 170 RH. A walking garden. Phase 1: walks a slow figure-eight and plants a Spore Pod every 8 s; it regenerates 2% HP/s while standing on creep, and creep spreads from its feet (SPREAD creep, tick 1.5 s), so burning its trail is the real damage race. Phase 2 (60%): spore burst every 10 s, a 6 m cloud around itself (1.5 s inflate telegraph); inside the cloud only its eyes show. Phase 3 (30%): roots itself in the centre (immune to knockback), sends creep tendrils along the four paths and hatches all egg clusters; destroying the four nearest pods makes it wilt for 5 s (takes double damage).", bossLook = "Bloater model at 2.6x, moss green #5c7a3a skin with pale yellow pus sacs #d8e070 (the Bloater pus material recoloured), 6 Spore Pod meshes parented on its back that inflate on the spore telegraph.",
                modifiers = new[] { "Overgrowth: creep starts on 25% of every floor.", "Pollen Storm: spore clouds last 12 s.", "Fertile Soil: egg clusters respawn 30 s after being destroyed.", "Sprinklers: blue zones become shallow WATER (slows, puts out creep)." },
                stars = new[] { "Clear the zone.", "No revive and under par (4:00).", "Beat Mother Bloom without letting her regenerate on creep for more than 5 s total." }, starBonus = "Destroy 30 Spore Pods before they puff.", par = 240,
                layoutNotes = new Dictionary<string, string> { {"verd-a", "Crop Rows. Long green hedgerows split the field into lanes; pods sit at lane ends."}, {"verd-b", "Greenhouse. Creep bloom in the middle beds fed by two nests; paths around the edge."}, {"verd-c", "Nest Orchard. Three nests in walled gardens, each ringed by eggs."}, {"verd-boss", "Central Garden. Four paths into a round bed; pods and eggs along the paths."} } },
            new SectorDef { id = "blackout-labs", name = "BLACKOUT LABS", num = 5, act = "I", power = 1400, tier = 2, art = "kessler", lat = 28.4f, lon = 27.0f, endless = false,
                blurb = "A research wing with the power cut", pitch = "A research wing with the power cut: you see only what your light, your flares and the pylons you relight can reach, and something in the dark is hunting you.", signature = "Auto-fire only targets enemies that are lit, so light is your range. Flares (3 charges, right-thumb button) light 7 m for 12 s and expose enemies (+20% damage); pylons are permanent but cost 1.5 s of standing still. Relighting the floor through relays is the objective on two floors. Electrified grates are a killing floor for the swarm, and a breaker can switch them off when they hurt you more than them. Stalkers (enemies doc) debut here, invisible even in light until hit.",
                unlockAny = new string[] { "kessler-refinery", "verdant-colony" }, unlockAfter = "kessler-refinery",
                floorTint = C(0xc9ced4), wallTint = C(0xeef1f4), accent = C(0xff2a2a), sun = C(0x0b0f18), sunIntensity = 1.1f, ambient = C(0x0b0f18), fog = C(0x05070a), fogStart = 8.0f, fogEnd = 30.0f, particles = Particles.Ash,
                order = new[] { Game.Goal.Purge, Game.Goal.Relay, Game.Goal.Survive, Game.Goal.Hunt, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Purge, spec = "PURGE", param = "3 waves", layout = "blackout-labs/black-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 42), new EnemyEntry("Tick", 8), new EnemyEntry("Spitter", 3) }, events = "Half-lit: dark 'd' rooms on both wings. First flare cache by the spawn with a hint. Spitter globs glow green in the dark, so they read.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Grab flares from the cache. Throw them into the dark to see and hit.\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Relay, spec = "RELAY", param = "3 relays", layout = "blackout-labs/black-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 44), new EnemyEntry("Leaper", 4), new EnemyEntry("Stalker", 2), new EnemyEntry("Tick", 8) }, events = "Floor fully dark. Relay 1 lights the west wing, relay 2 the east wing, relay 3 powers the grates (they start cycling) and ends the floor. Breaker by relay 3.", script = "[{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.1,\"area\":\"all\"}},{\"when\":{\"start\":true},\"do\":\"TOGGLE\",\"params\":{\"system\":\"GRATE\",\"state\":\"off\"}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":1}},\"do\":\"LIGHT\",\"params\":{\"level\":1,\"area\":{\"cols\":[0,11]}}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":2}},\"do\":\"LIGHT\",\"params\":{\"level\":1,\"area\":{\"cols\":[12,23]}}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":3}},\"do\":\"TOGGLE\",\"params\":{\"system\":\"GRATE\",\"state\":\"cycle\",\"warn\":0.8}}]" },
                    new ZoneFloor { goal = Game.Goal.Survive, spec = "SURVIVE", param = "50 s, 'Lights Out'", layout = "blackout-labs/black-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 58), new EnemyEntry("Leaper", 5), new EnemyEntry("Stalker", 3), new EnemyEntry("Bloater", 1), new EnemyEntry("Shrieker", 1) }, events = "Full dark, 6 unlit pylons and 2 flare caches. Every 15 s a power surge lights the whole floor for 1 s (flash), showing every enemy at once.", script = "[{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.1,\"area\":\"all\"}},{\"when\":{\"every\":{\"s\":15}},\"do\":\"LIGHT\",\"params\":{\"level\":1,\"area\":\"all\",\"flash\":1}},{\"when\":{\"every\":{\"s\":15,\"from\":12}},\"do\":\"CUE\",\"params\":{\"id\":\"surge_countdown\",\"beats\":3}}]" },
                    new ZoneFloor { goal = Game.Goal.Hunt, spec = "HUNT", param = "3 nests", layout = "blackout-labs/black-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 50), new EnemyEntry("Leaper", 5), new EnemyEntry("Carapace", 2), new EnemyEntry("Stalker", 3), new EnemyEntry("Spitter", 4) }, events = "Same wing, lights back off, nests grown where the relays were. Grates on from the start; the breaker is now a choice.", script = "[{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.1,\"area\":\"all\"}},{\"when\":{\"start\":true},\"do\":\"TOGGLE\",\"params\":{\"system\":\"GRATE\",\"state\":\"cycle\"}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"The breaker kills the grates. They also kill the swarm: your call.\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "blackout-labs/black-boss", enemies = new EnemyEntry[] { new EnemyEntry("Subject Zero", 1), new EnemyEntry("Stalker", 4), new EnemyEntry("Drone", 16) }, events = "Containment hall. Four pylons, grates around the centre, two breakers.", script = "[{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.1,\"area\":\"all\"}},{\"when\":{\"boss_hp\":0.3},\"do\":\"CLOSE\",\"params\":{\"target\":\"I\"}},{\"when\":{\"boss_hp\":0.3},\"do\":\"DROP\",\"params\":{\"kind\":\"flare\",\"at\":\"hero\",\"refill\":3}}]" },
                },
                mechanics = new[] { "DARKNESS", "GRATE", "INTERACT", "NEST" },
                boss = "Subject Zero", bossBody = "HP 150 RH. An albino Leaper the lab was studying. It is invisible outside light (eye glints only) and takes double damage while exposed by a flare or pylon. Phase 1: stalks and pounces from the dark (its red arrow is the only warning; the arrow is always visible). Phase 2 (60%): smashes a lit pylon every 15 s (relight it in 1.5 s) and spawns 2 Stalkers. Phase 3 (30%): kills the lights entirely (pylons off, flares refill to 3) and pounces in a chain of three; luring a pounce onto a live grate stuns it 3 s and lights it up (it glows blue while stunned).", bossLook = "Leaper model at 2.0x, bone white #f2efe8 with no texture detail, pale pink emissive eyes, bright cyan sparks when on a grate.",
                modifiers = new[] { "Dead Batteries: hero light radius 4 m.", "Flare Shortage: 1 flare charge, caches give 1.", "Surge: grates on 2.4 s each cycle.", "Night Shift: every Drone group includes a Stalker." },
                stars = new[] { "Clear the zone.", "No revive and under par (4:30).", "Kill 50 enemies with electrified grates." }, starBonus = "Clear while using at most 4 flares.", par = 270,
                layoutNotes = new Dictionary<string, string> { {"black-a", "Two Wings. Lit central atrium, dark wings ('d') on both sides with a flare cache by the spawn."}, {"black-b", "Relay Wing. Three relays spaced around a U-shaped corridor; grates across the main corridor; breaker next to relay 3."}, {"black-c", "Server Hall. Open dark hall with server rows (B), six pylons and two flare caches."}, {"black-boss", "Containment. Grate cross in the middle, four pylons at the corners of the cross, two breakers."} } },
            new SectorDef { id = "drowned-city", name = "DROWNED CITY", num = 6, act = "II", power = 1600, tier = 2, art = "drowned", lat = 22.7f, lon = 164.5f, endless = false,
                blurb = "A flooded colony district where the tide is the clock", pitch = "A flooded colony district where the tide is the clock: water slows you, live cables turn it into a trap, and on one floor a flood surge chases you to the lift.", signature = "Water slows you (shallow -20%, deep -45%) but dash is never slowed, so every fight becomes a question of where the dry ground is. Floods spread on a 20 s pulse; pumps drain them. Grates that touch water electrify the whole connected pool on their beat, which is the best killing tool in the zone and the biggest danger to you. The OUTRUN floor debuts here: a flood surge sweeps the map and you race it to the lift.",
                unlockAny = new string[] { "blackout-labs" }, unlockAfter = "blackout-labs",
                floorTint = C(0x2e3338), wallTint = C(0x5a6670), accent = C(0x3e5a44), sun = C(0xb8c8d8), sunIntensity = 0.6f, ambient = C(0xa0a8b8), fog = C(0x6f8291), fogStart = 6.0f, fogEnd = 72.0f, particles = Particles.Rain,
                order = new[] { Game.Goal.Purge, Game.Goal.Relay, Game.Goal.Outrun, Game.Goal.Hold, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Purge, spec = "PURGE", param = "3 waves", layout = "drowned-city/drown-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 46), new EnemyEntry("Spitter", 4), new EnemyEntry("Tick", 8), new EnemyEntry("Leaper", 3) }, events = "Shallow streets, dry pavements. One live cable (grate) in the main street pool: the first wave walks into it to show what it does.", script = "[{\"when\":{\"wave\":{\"n\":1,\"at\":\"start\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Drone\",\"count\":8,\"at\":\"far_S\",\"group\":\"pack\",\"route\":\"g\"}},{\"when\":{\"t\":6},\"do\":\"HINT\",\"params\":{\"text\":\"Live cable: the whole pool is electrified on its beat.\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Relay, spec = "RELAY", param = "3 pumps", layout = "drowned-city/drown-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 48), new EnemyEntry("Leaper", 4), new EnemyEntry("Burrower", 2), new EnemyEntry("Spitter", 4) }, events = "Each pump (R, 3 s) drains a third of the flood. The floor floods every 20 s until all three run. Burrowers cannot surface in water, so they surface on the dry ground you need.", script = "[{\"when\":{\"every\":{\"s\":20}},\"do\":\"FLOOD\",\"params\":{\"spread_s\":8,\"depth\":1}},{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"WATER\",\"pump_drain\":0.33}}]" },
                    new ZoneFloor { goal = Game.Goal.Outrun, spec = "OUTRUN", param = "flood surge west to east, 1.2 m/s", layout = "drowned-city/drown-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 40), new EnemyEntry("Leaper", 5), new EnemyEntry("Tick", 10), new EnemyEntry("Carapace", 1) }, events = "Surge starts behind the spawn after 5 s. Two bulkhead valves (R) pause it 4 s. Enemies spawn ahead of you and ride the surge.", script = "[{\"when\":{\"start\":true},\"do\":\"FRONT\",\"params\":{\"skin\":\"flood\",\"dir\":\"E\",\"speed\":1.2,\"countdown\":5,\"state\":\"start\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Hold, spec = "HOLD", param = "35 s on the plaza", layout = "drowned-city/drown-d", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 60), new EnemyEntry("Leaper", 5), new EnemyEntry("Spitter", 5), new EnemyEntry("Bloater", 1), new EnemyEntry("Shrieker", 1) }, events = "The ring is on a dry plaza; the water around it rises every 15 s (deep from 20 s). Breaker K kills the grates if you need the plaza edges safe.", script = "[{\"when\":{\"every\":{\"s\":15,\"from\":5}},\"do\":\"FLOOD\",\"params\":{\"spread_s\":8,\"depth\":1}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Shoot the breaker to kill the grates if you need the plaza edges safe.\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "drowned-city/drown-boss", enemies = new EnemyEntry[] { new EnemyEntry("Tidecaller", 1), new EnemyEntry("Drone", 20), new EnemyEntry("Burrower", 2) }, events = "Sunken square with two deep pools and grates on their rims. The boss swims.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Pool terminals electrify the pools for 5 s. Catch Tidecaller submerged.\"}},{\"when\":{\"done\":{\"kind\":\"terminal\"}},\"do\":\"SET\",\"params\":{\"system\":\"GRATE\",\"on\":5,\"off\":0,\"for\":5,\"rearm\":15}}]" },
                },
                mechanics = new[] { "WATER", "GRATE", "FRONT", "INTERACT" },
                boss = "Tidecaller", bossBody = "HP 180 RH. Travels submerged in deep water (untargetable, a wake trail shows where it is) and surfaces to attack. Phase 1: surfaces under you with a Burrower-style ring (2.2 m, 1.0 s warning) when you stand in water, then stays up 3 s. Phase 2 (60%): floods the square every 12 s (water +1 depth step); spits Spitter globs from the pools. Phase 3 (30%): whips a 10 m water lash in a line (red lane 0.8 s). Counter: the two pool terminals (R) switch the grates to 'always on' for 5 s; if Tidecaller is submerged in an electrified pool it is forced up, stunned 3 s and takes 10% max HP.", bossLook = "Leaper model at 2.5x with the legs hidden under the water plane, sea-green #2f6f62 skin, cyan emissive gill slits #5fd8ff, water-splash particles (smoke recoloured white-blue) on surfacing.",
                modifiers = new[] { "High Tide: every 'w' starts deep.", "Storm: lightning STRIKE every 9 s (COVER: none, so keep moving).", "Short Circuit: grates cycle at random intervals.", "Riptide: deep water pushes 1.5 m/s toward the nearest pool." },
                stars = new[] { "Clear the zone.", "No revive and under par (4:30).", "Finish the OUTRUN floor without the surge touching you." }, starBonus = "Kill 60 enemies with electrified water.", par = 270,
                layoutNotes = new Dictionary<string, string> { {"drown-a", "Flooded Avenue. A main street pool with one live cable, dry pavements on both sides, raised blue-zone rooftops (dry, ~) in the corners."}, {"drown-b", "Pump Station. Three pumps around a flooded basin with grates on the basin rim."}, {"drown-c", "Canal Run. Long west-to-east canal street for the surge; two bulkhead valves on the way; lift at the east end."}, {"drown-d", "Plaza Island. Dry plaza ring in the middle, water all around, breaker on the south edge."}, {"drown-boss", "Sunken Square. Two deep pools with grates on the rims and a pool terminal beside each."} } },
            new SectorDef { id = "cargo-port", name = "HADLEY CARGO PORT", num = 7, act = "II", power = 1800, tier = 2, art = "drowned", lat = 17.4f, lon = -58.0f, endless = false,
                blurb = "A storm-lashed container terminal still running on autopilot", pitch = "A storm-lashed container terminal still running on autopilot: belts herd the swarm, cranes drop steel boxes that rebuild the map mid-fight, and the cargo lifts throw you between split decks.", signature = "The port is a machine you play. Belts add 3 m/s to everything on them, so running with a belt outruns any Drone and running against it is a trap; packs that follow you onto a belt get carried into the pits and the press at its end. Crane STRIKES drop containers (35 HP, 12 RH, then a C crate stays for the rest of the floor), so every few seconds the arena loses a lane and gains a wall: Carapace charges have new walls to stun on, Lancers lose sightlines, and your kiting circle has to change shape. Turrets on the quay pull half the swarm off you while they fire. Split decks joined only by cargo-lift jump pads let you reset a fight by leaving it, but Leapers pounce after you.",
                unlockAny = new string[] { "blackout-labs" }, unlockAfter = "blackout-labs",
                floorTint = C(0x2f3236), wallTint = C(0x8a3324), accent = C(0x1f7a7a), sun = C(0xffb35c), sunIntensity = 0.95f, ambient = C(0x3a4656), fog = C(0x56636f), fogStart = 20.0f, fogEnd = 55.0f, particles = Particles.Rain,
                order = new[] { Game.Goal.Purge, Game.Goal.Escort, Game.Goal.Uplink, Game.Goal.Survive, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Purge, spec = "PURGE", param = "3 waves", layout = "cargo-port/port-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 34), new EnemyEntry("Tick", 6), new EnemyEntry("Leaper", 3), new EnemyEntry("Splitter", 2) }, events = "Teach belts: the two long belts run in opposite directions and both end in a pit. Wave 1 enters from the top corners so it has to cross the east belt. One crane drop per wave, always on an empty lane, with the first one played as a slow 3 s demo (shadow, whine, CLANG). The turret on the north quay is pre-captured for 10 s to show what it does.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Belts carry everything. Run with them; lure packs onto them and into the pits.\"}},{\"when\":{\"start\":true},\"do\":\"CAPTURE\",\"params\":{\"target\":1,\"owner\":\"hero\",\"for\":10}},{\"when\":{\"wave\":{\"n\":1,\"at\":\"start\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Drone\",\"count\":12,\"at\":\"S\",\"index\":[1,2],\"group\":\"pack\"}},{\"when\":{\"wave\":{\"n\":1,\"at\":\"start\"}},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":1,\"radius\":2,\"delay\":3.0,\"leaves\":\"container\",\"skin\":\"container\",\"aim\":\"empty_lane\"}},{\"when\":{\"wave\":{\"n\":2,\"at\":\"start\"}},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":1,\"radius\":2,\"delay\":1.5,\"leaves\":\"container\",\"skin\":\"container\",\"aim\":\"empty_lane\"}},{\"when\":{\"wave\":{\"n\":3,\"at\":\"start\"}},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":1,\"radius\":2,\"delay\":1.5,\"leaves\":\"container\",\"skin\":\"container\",\"aim\":\"empty_lane\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Escort, spec = "ESCORT", param = "cart along the rail spur, 400 HP", layout = "cargo-port/port-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 38), new EnemyEntry("Tick", 8), new EnemyEntry("Leaper", 4), new EnemyEntry("Carapace", 2), new EnemyEntry("Spitter", 4) }, events = "The payload is a reefer container on a flatbed cart (cargo crate model 1.2x on a barrel-chassis). Twist: the crane targets the track. Every 14 s a container lands ON the ':' path ahead of the cart (red circle, 1.5 s) and blocks it until shot down (20 RH, low-priority auto-fire target, explosions x3). Carapaces spawn at the two bends; bait their charges into the blocking containers to stun them and break the box in one go. Capturing the mid-track turret covers the long straight.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Containers block the cart. Bait Carapace charges into them.\"}},{\"when\":{\"every\":{\"s\":14}},\"do\":\"STRIKE\",\"params\":{\"mode\":\"fixed\",\"cells\":\":\",\"count\":1,\"radius\":2,\"delay\":1.5,\"leaves\":\"container\",\"skin\":\"container\",\"aim\":\"ahead_of_cart\",\"block_hp\":20,\"explosion_mult\":3,\"blocks_cart\":true}},{\"when\":{\"progress\":0.3},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Carapace\",\"count\":1,\"at\":\"ahead\",\"group\":\"pack\"}},{\"when\":{\"progress\":0.65},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Carapace\",\"count\":1,\"at\":\"ahead\",\"group\":\"pack\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Uplink, spec = "UPLINK", param = "30 s, ring hops between decks", layout = "cargo-port/port-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 40), new EnemyEntry("Leaper", 6), new EnemyEntry("Tick", 8), new EnemyEntry("Spitter", 4), new EnemyEntry("Shrieker", 1) }, events = "Split decks: the UPLINK ring relocates between the west and east decks, so the hero has to take the cargo lifts (jump pads) or the one-way belt gantry across the pit. Leapers pounce across the 2-cell pit after you; Drones have to walk round, so every deck change sheds the pack for 4-5 s. A Shrieker holds the east deck from the second relocation; crane drops now land 2 at a time.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Ride the cargo lifts. Drones have to walk round.\"}},{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":1,\"radius\":2,\"interval\":10,\"leaves\":\"container\",\"skin\":\"container\"}},{\"when\":{\"progress\":0.5},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Shrieker\",\"count\":1,\"at\":\"S\",\"index\":[2],\"group\":\"pack\"}},{\"when\":{\"progress\":0.5},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":2,\"radius\":2,\"interval\":10,\"leaves\":\"container\",\"skin\":\"container\"}},{\"when\":{\"progress\":0.5},\"do\":\"HINT\",\"params\":{\"text\":\"CARGO LIFTS DOWN: TAKE THE GANTRY\"}},{\"when\":{\"progress\":0.5},\"do\":\"CUE\",\"params\":{\"id\":\"power_down\"}},{\"when\":{\"progress\":0.5},\"do\":\"TOGGLE\",\"params\":{\"system\":\"CONVEYOR\",\"state\":\"off\"}},{\"when\":{\"progress\":0.5},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":1,\"radius\":2,\"interval\":4,\"skin\":\"container\",\"aim\":\"J\",\"for\":10}},{\"when\":{\"progress\":0.5},\"do\":\"HINT\",\"params\":{\"text\":\"CRANE PANIC: TIME YOUR JUMPS\"}},{\"when\":{\"progress\":0.5},\"do\":\"CUE\",\"params\":{\"id\":\"crane_panic\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Survive, spec = "SURVIVE", param = "60 s", layout = "cargo-port/port-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 46), new EnemyEntry("Tick", 10), new EnemyEntry("Leaper", 5), new EnemyEntry("Carapace", 3), new EnemyEntry("Splitter", 3), new EnemyEntry("Spitter", 4) }, events = "Container Storm: crane drops every 5 s, 2-3 at a time, and the belts reverse at 20 s and 40 s (chevrons flash 1.5 s first). By 60 s the yard is a maze of fresh crates. Both turrets are live; holding one while a Carapace charges it is the floor's big play. Spike at 30 s: a Splitter trio rides the east belt in.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Container Storm. Hold a turret and let the Carapace charge it.\"}},{\"when\":{\"every\":{\"s\":10,\"from\":5}},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":2,\"radius\":2,\"leaves\":\"container\",\"skin\":\"container\"}},{\"when\":{\"every\":{\"s\":10,\"from\":10}},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":1,\"radius\":2,\"leaves\":\"container\",\"skin\":\"container\"}},{\"when\":{\"t\":20},\"do\":\"TOGGLE\",\"params\":{\"system\":\"CONVEYOR\",\"state\":\"off\",\"warn\":1.5}},{\"when\":{\"t\":20},\"do\":\"HINT\",\"params\":{\"text\":\"BELTS DOWN: POWER TO THE CRANES\"}},{\"when\":{\"t\":20},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":2,\"radius\":2,\"leaves\":\"container\",\"skin\":\"container\"}},{\"when\":{\"t\":30},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Splitter\",\"count\":3,\"at\":\"far_S\",\"group\":\"pack\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "cargo-port/port-boss", enemies = new EnemyEntry[] { new EnemyEntry("Hullbreaker", 1), new EnemyEntry("Tick", 16), new EnemyEntry("Drone", 18), new EnemyEntry("Carapace", 2) }, events = "Crusher Bay. Four north-running belts feed the press line on the top row (y), which slams every 6 s with a 1.2 s red flash. The boss is only stunned by walls and containers, and only the press really hurts it, so the fight is about where its charges end.", script = "[{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"fixed\",\"cells\":\"y\",\"interval\":6,\"delay\":1.2,\"radius\":1,\"skin\":\"press\",\"boss_damage\":25}},{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":2,\"radius\":2,\"interval\":10,\"leaves\":\"container\",\"skin\":\"container\"}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Make it charge into steel. Then let the belts feed it to the press.\"}},{\"when\":{\"boss_hp\":0.3},\"do\":\"SET\",\"params\":{\"system\":\"CONVEYOR\",\"dir\":\"N\",\"cells\":\"all\",\"warn\":1.5}},{\"when\":{\"start\":true},\"do\":\"TOGGLE\",\"params\":{\"system\":\"TURRET\",\"state\":\"off\"}},{\"when\":{\"boss_hp\":0.6},\"do\":\"TOGGLE\",\"params\":{\"system\":\"TURRET\",\"state\":\"on\"}}]" },
                },
                mechanics = new[] { "CONVEYOR", "STRIKE", "JUMP_PAD", "TURRET", "PIT" },
                boss = "Hullbreaker", bossBody = "A dock-hauler Carapace grown to the size of a forklift, plated with the containers it has crushed. Phase 1 (100-60%): Charge Lanes. Yellow lane telegraph (1.0 s), then a charge; a charge that runs WITH a belt goes 1.5x farther, against it 0.5x. Hitting a crate or container stuns it 3.5 s with its soft back exposed. The crane drops 2 containers every 10 s, which are new charge-bait. Phase 2 (60-30%): Lift and Hurl. It rips up the nearest container (1.2 s lift, the box hangs over its head) and hurls it at the hero: a STRIKE circle that leaves a C crate, and each container it breaks releases 4 Ticks. The two turrets come online; it hates them and charges any captured turret, so a captured turret is a lure that turns its back to you. Phase 3 (30-0%): Feed the Press. All belts switch to run north into the press line. A stunned Hullbreaker standing on a belt is carried into the press: 25 RH per slam, and its plating breaks off (front armour gone for 8 s). The counterplay is matador positioning: stand with a container or the press behind you, sidestep at the lock, and let the belt deliver it. Enrage at 15%: two charges back to back.", bossLook = "Bloater model at 2.4x, squashed to 0.6x height (the Carapace recipe), tinted rust #7a3b1e with a hazard-yellow #f2c230 emissive strip on the front half; two cargo crate models at 0.35x tinted Hadley teal #1f7a7a bolted on its back as plates (they fall off in Phase 3). Name banner: HULLBREAKER, 'It moves the freight now.'",
                modifiers = new[] { "Gale Warning: WIND gusts every 12 s push toward the quay pits; crates give wind shadow.", "Overtime: belts run at 5 m/s and reverse every 15 s.", "Live Cargo: every crane container cracks open after landing and releases 3 Ticks.", "Night Shift: floodlights fail; DARKNESS with light pylons on every crane mast." },
                stars = new[] { "Clear the zone.", "No revive and under par (4:00).", "Finish the ESCORT floor with the cart above 50% HP." }, starBonus = "Kill 30 enemies with belts (carried into a pit or the press) in one run.", par = 240,
                layoutNotes = new Dictionary<string, string> { {"port-a", "Container Yard. Two long opposed belts cut the yard into three strips, each ending in a pit; two turrets on the quays; crate stacks to bait charges."}, {"port-b", "Rail Spur. A staircase track crosses the yard on a diagonal from the north-west to the south-east; crate stacks crowd the bends where the Carapaces wait."}, {"port-c", "Split Decks. Two decks split by a 2-cell drop, joined by two pairs of cargo lifts and a one-way east belt gantry; four uplink rings alternate decks."}, {"port-boss", "Crusher Bay. Press line along the north wall, four belts feeding it, crates mid-field as charge stops, a west belt across the south."} } },
            new SectorDef { id = "acid-marsh", name = "ACID MARSH", num = 8, act = "II", power = 2100, tier = 3, art = "verdant", lat = 12.3f, lon = 79.6f, endless = false,
                blurb = "A drowned agri-dome turned into a green, steaming swamp where the sky itself burns", pitch = "A drowned agri-dome turned into a green, steaming swamp where the sky itself burns: run between roofs when the rain comes, and push the creep back with fire.", signature = "The rain sets the rhythm. Every 20 s you have 3 s to reach a roof, and 4 s of rain where open ground costs 6 HP per half second; but the rain also eats 4% of every exposed enemy's HP per tick, so the best players stand under a roof and let the swarm melt in the open around them. Spitters (featured, x3 weight) leave puddles that stack with the static acid pools, so safe ground shrinks; spore pods hide packs in clouds you have to burn or blast. Creep grows from nests and makes you slow and them fast, and fire (dash, barrels, Incendiary) is the only way to win ground back.",
                unlockAny = new string[] { "drowned-city" }, unlockAfter = "drowned-city",
                floorTint = C(0x1d221a), wallTint = C(0x5a5f52), accent = C(0x8fbf4a), sun = C(0xd6e88a), sunIntensity = 0.8f, ambient = C(0x39452e), fog = C(0x6e7f4a), fogStart = 6.0f, fogEnd = 51.4f, particles = Particles.Rain,
                order = new[] { Game.Goal.Purge, Game.Goal.Defend, Game.Goal.Hold, Game.Goal.Survive, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Purge, spec = "PURGE", param = "3 waves", layout = "acid-marsh/marsh-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 32), new EnemyEntry("Spitter", 8), new EnemyEntry("Tick", 6), new EnemyEntry("Splitter", 2) }, events = "Teach rain: the first pulse comes at 15 s with a long 5 s warning and a 'GET UNDER COVER' hint pointing to the nearest roof. Enemies caught in the rain visibly sizzle and the first kill by rain pops a 'THE RAIN HURTS THEM TOO' toast. Spitters arrive in wave 2 in pairs from across the central acid ring.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"ACID_RAIN\",\"state\":\"on\",\"period\":20,\"first\":15,\"first_warn\":5}},{\"when\":{\"t\":10},\"do\":\"HINT\",\"params\":{\"text\":\"GET UNDER COVER\",\"point_to\":\"nearest_u\"}},{\"when\":{\"wave\":{\"n\":2,\"at\":\"start\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Spitter\",\"count\":2,\"at\":\"far_S\",\"group\":\"pack\"}},{\"when\":{\"wave\":{\"n\":2,\"at\":\"start\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Spitter\",\"count\":2,\"at\":\"far_S\",\"group\":\"pack\",\"delay\":6}}]" },
                    new ZoneFloor { goal = Game.Goal.Defend, spec = "DEFEND", param = "purifier, 45 s", layout = "acid-marsh/marsh-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 40), new EnemyEntry("Spitter", 8), new EnemyEntry("Tick", 8), new EnemyEntry("Carapace", 2), new EnemyEntry("Spore Pod", 4) }, events = "Twist: the purifier G sits under the only big roof, and it is immune to rain but not to Spitters. Four Spore Pods are pre-placed on the approaches; their clouds hide the packs walking to the purifier. Rain at 10 s, 30 s. At 25 s the purifier vents (a 4 m green burst) that clears every puddle and spore cloud around it: a breather if you stayed close.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"ACID_RAIN\",\"state\":\"on\",\"period\":20,\"first\":10}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Rain can't hurt the purifier. Spitters can.\"}},{\"when\":{\"t\":25},\"do\":\"SET\",\"params\":{\"system\":\"ACID_POOL\",\"clear_puddles\":true,\"at\":\"G\",\"radius\":4}},{\"when\":{\"t\":25},\"do\":\"SET\",\"params\":{\"system\":\"SPORE_POD\",\"clear_clouds\":true,\"at\":\"G\",\"radius\":4}}]" },
                    new ZoneFloor { goal = Game.Goal.Hold, spec = "HOLD", param = "30 s on the storm beacon, no roof", layout = "acid-marsh/marsh-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 44), new EnemyEntry("Spitter", 6), new EnemyEntry("Leaper", 5), new EnemyEntry("Burrower", 2), new EnemyEntry("Spore Pod", 3) }, events = "Rot Fields: three nests feed creep across the fields. Rows of red barrels sit on the creep; every barrel chain scorches a band. Kill the nests first or the creep keeps outgrowing you. Acid rain does not scorch creep, but enemies on creep regenerate through it, so rain is weaker here: the zone's lesson flips. An Incendiary Rounds drop is guaranteed at 20 s.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"ACID_RAIN\",\"state\":\"on\",\"period\":20}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"STORM BEACON: NO ROOF. HOLD THROUGH THE RAIN.\"}},{\"when\":{\"every\":{\"s\":20,\"from\":17}},\"do\":\"CUE\",\"params\":{\"id\":\"beacon_charge\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Survive, spec = "SURVIVE", param = "60 s", layout = "acid-marsh/marsh-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 50), new EnemyEntry("Spitter", 10), new EnemyEntry("Tick", 10), new EnemyEntry("Leaper", 5), new EnemyEntry("Splitter", 3), new EnemyEntry("Mender", 1) }, events = "Monsoon: rain every 12 s, and each roof corrodes: after 2 pulses a roof slab drips, hisses and falls (it becomes rubble, a C for 15 s, then open floor). By the end only two roofs stand, so the hero is forced to migrate across the map between pulses. A Mender at 30 s heals a Carapace-less pack, and the rain cannot kill what it heals: find it.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"ACID_RAIN\",\"state\":\"on\",\"period\":12}},{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"COVER\",\"corrode_after_pulses\":2,\"rubble_s\":15,\"min_standing\":2}},{\"when\":{\"t\":30},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Mender\",\"count\":1,\"at\":\"far_S\",\"group\":\"pack\"}},{\"when\":{\"t\":30},\"do\":\"HINT\",\"params\":{\"text\":\"Something is healing them. Find the Mender.\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "acid-marsh/marsh-boss", enemies = new EnemyEntry[] { new EnemyEntry("Mire Matriarch", 1), new EnemyEntry("Spitter", 6), new EnemyEntry("Drone", 20), new EnemyEntry("Tick", 8) }, events = "Mire Pit: an arena of acid pools with six roofs. Rain pulses every 20 s all fight and hurt the boss too, but only while she is outside cover.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"ACID_RAIN\",\"state\":\"on\",\"period\":20,\"boss_damage_per_tick\":3}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"She shelters before the rain. Pull her into the open.\"}},{\"when\":{\"boss_hp\":0.3},\"do\":\"SET\",\"params\":{\"system\":\"ACID_RAIN\",\"period\":10}}]" },
                },
                mechanics = new[] { "ACID_RAIN", "COVER", "ACID_POOL", "SPREAD", "SPORE_POD", "NEST", "WATER" },
                boss = "Mire Matriarch", bossBody = "HP 220. Phase 1 (100-65%): the doc's Volley (5 globs in a fan) and Acid Field (30% of the floor turns to acid for 6 s, always with a safe path). Twist: she walks under a roof before every rain pulse and is immune there, so the hero has to drag her out with Volley range (she keeps 10-14 m away and backs off when you push). A Matriarch caught in the rain takes 3 RH per tick and shrieks. Phase 2 (65-30%): Pool Dive. She sinks into an acid pool (1.0 s) and surfaces from another one 2 s later, with a green ring telegraph on the target pool; two Spitters climb out of the pool she left. Spore Pods sprout on her surface spots. Shoot pods before she arrives or the next volley comes out of a cloud. Phase 3 (30-0%): Bring the Storm. She calls the rain herself every 10 s and starts melting roofs she stands under (3 s). Corroded roofs fall like Monsoon. Counterplay: keep a roof between you and her line, and bait her into ones that are already melting. Death: a 6 m acid burst that also scorches all creep in the arena.", bossLook = "Spitter placeholder (Drone model) at 3.0x, tinted bile green #6f9a2a with a toxic #9bff3a emissive abdomen sphere 1.8x larger than the Spitter's, a crown of six Lancer spikes, and a dripping green particle trail. Name banner: MIRE MATRIARCH, 'Mother of the rain.'",
                modifiers = new[] { "Acid Downpour: rain every 12 s instead of 20 s.", "Overgrowth: creep starts on 25% of floor cells on every floor and grows 30% faster.", "Toxic Swarm: 20% of enemies gain the Toxic modifier (acid trails).", "Leaky Roofs: every roof stops protecting 1 s before the rain ends." },
                stars = new[] { "Clear the zone.", "No revive and under par (4:15).", "Clear the boss without taking acid rain damage." }, starBonus = "Let the acid rain kill 40 enemies in one run.", par = 255,
                layoutNotes = new Dictionary<string, string> { {"marsh-a", "Boardwalk. A broken acid ring around a central island, boardwalk gaps on the diagonals, roofs and shallow ponds in the corners."}, {"marsh-b", "Pump Island. Purifier under a 3x2 roof in the centre, acid channels running diagonally, four spore pods on the approaches, small roofs spread to the edges."}, {"marsh-c", "Rot Fields. Long creep fields between rows of feed bins, three nests in a triangle, barrel rows across the creep."}, {"marsh-boss", "Mire Pit. Six acid pools for the Matriarch to dive between, six roofs, open mud between."} } },
            new SectorDef { id = "data-vault", name = "HELIX DATA VAULT", num = 9, act = "II", power = 2400, tier = 3, art = "cryo", lat = 7.3f, lon = -142.9f, endless = false,
                blurb = "A cold, humming server fortress the hive is trying to read", pitch = "A cold, humming server fortress the hive is trying to read: steal its cores through laser lattices and dark aisles while cloaked Stalkers hunt you between the racks.", signature = "The vault is a timing puzzle under fire. Laser fences turn aisles into gates that open 3 s in every 8, so you plan routes on the beat; grates are death floors for the swarm when they pulse and the breaker is a one-way choice (switch them off to be safe, or keep them to keep killing). Dark aisles hide Stalkers (featured) and only the hero's light and light pylons expose them; turrets watch the long aisles and pull the swarm off you. Fewer enemies than other Act II zones, but every one of them is a question.",
                unlockAny = new string[] { "cargo-port" }, unlockAfter = "cargo-port",
                floorTint = C(0x15181c), wallTint = C(0x101317), accent = C(0x39d7ff), sun = C(0xcfefff), sunIntensity = 0.7f, ambient = C(0x1a2a36), fog = C(0x0e1a22), fogStart = 18.0f, fogEnd = 45.0f, particles = Particles.None,
                order = new[] { Game.Goal.Purge, Game.Goal.Salvage, Game.Goal.Relay, Game.Goal.Assassinate, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Purge, spec = "PURGE", param = "3 waves", layout = "data-vault/vault-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 36), new EnemyEntry("Tick", 6), new EnemyEntry("Leaper", 4), new EnemyEntry("Splitter", 2), new EnemyEntry("Weaver", 1) }, events = "Server Hall. Teach grates: the four aisle grates pulse in sync and wave 1 runs straight across them, so the first pulse kills half a pack and a 'LURE THEM ACROSS' hint fires. The breaker K in the north-east corner is shown with a 'shoot to switch off grates for good' tooltip; most players should learn to leave it.", script = "[{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"GRATE\",\"sync\":true}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Breaker: shoot to switch off grates for good.\",\"point_to\":\"K\"}},{\"when\":{\"wave\":{\"n\":1,\"at\":\"start\"}},\"do\":\"HINT\",\"params\":{\"text\":\"LURE THEM ACROSS\",\"delay\":4.8}}]" },
                    new ZoneFloor { goal = Game.Goal.Salvage, spec = "SALVAGE", param = "5 of 6 cores", layout = "data-vault/vault-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 34), new EnemyEntry("Tick", 8), new EnemyEntry("Leaper", 4), new EnemyEntry("Stalker", 2), new EnemyEntry("Spitter", 4) }, events = "Cold Storage. Six data cores in the cold aisles, three of them in dark (d) bays. Each pickup triggers its ambush from the nearest S and the vault voice reads out a 'LOCKDOWN' that switches the laser fences to 4 s on / 4 s off for 10 s. First Stalkers: they wait in the dark bays and de-cloak on the hero as he grabs a core. Two light pylons let you pre-light a bay before you go in.", script = "[{\"when\":{\"start\":true},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Stalker\",\"count\":2,\"at\":\"d\",\"group\":\"spread\",\"state\":\"ambush\"}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Light a pylon before you enter a dark bay.\",\"point_to\":\"I\"}},{\"when\":{\"done\":{\"kind\":\"pickup\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Drone\",\"count\":4,\"at\":\"nearest_S\",\"group\":\"pack\"}},{\"when\":{\"done\":{\"kind\":\"pickup\"}},\"do\":\"SET\",\"params\":{\"system\":\"LASER_FENCE\",\"on\":4,\"off\":4,\"for\":10}},{\"when\":{\"done\":{\"kind\":\"pickup\"}},\"do\":\"CUE\",\"params\":{\"id\":\"vault_lockdown\"}},{\"when\":{\"done\":{\"kind\":\"pickup\",\"count\":5}},\"do\":\"LIGHT\",\"params\":{\"level\":0,\"area\":\"all\"}},{\"when\":{\"done\":{\"kind\":\"pickup\",\"count\":5}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Stalker\",\"count\":4,\"at\":\"ring\",\"group\":\"spread\",\"state\":\"ambush\"}},{\"when\":{\"done\":{\"kind\":\"pickup\",\"count\":5}},\"do\":\"SET\",\"params\":{\"system\":\"LASER_FENCE\",\"on\":4,\"off\":4}},{\"when\":{\"done\":{\"kind\":\"pickup\",\"count\":5}},\"do\":\"HINT\",\"params\":{\"text\":\"PURGE PROTOCOL: REACH THE LIFT\"}},{\"when\":{\"done\":{\"kind\":\"pickup\",\"count\":5}},\"do\":\"CUE\",\"params\":{\"id\":\"vault_purge\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Relay, spec = "RELAY", param = "3 relays in order", layout = "data-vault/vault-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 44), new EnemyEntry("Tick", 8), new EnemyEntry("Leaper", 5), new EnemyEntry("Carapace", 2), new EnemyEntry("Stalker", 2), new EnemyEntry("Shrieker", 1) }, events = "Firewall Ring. The relays sit in a ring around the core room, each behind a laser fence. Relay 1 opens the inner fence of the west wing and turns on the first turret; relay 2 switches every grate on (the swarm now has to cross them to reach you); relay 3 drops the core room's fences and ends the floor. Each relay is 3 s, but taking a hit knocks 15% off, so clear the room or capture the turret first.", script = "[{\"when\":{\"start\":true},\"do\":\"TOGGLE\",\"params\":{\"system\":\"GRATE\",\"state\":\"off\"}},{\"when\":{\"start\":true},\"do\":\"CLOSE\",\"params\":{\"target\":\"T\"}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Hits knock 15% off a relay. Clear the room first.\"}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":1}},\"do\":\"TOGGLE\",\"params\":{\"system\":\"LASER_FENCE\",\"state\":\"off\",\"index\":[1]}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":1}},\"do\":\"OPEN\",\"params\":{\"target\":\"T\",\"index\":1}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":2}},\"do\":\"TOGGLE\",\"params\":{\"system\":\"GRATE\",\"state\":\"on\",\"warn\":0.8}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":3}},\"do\":\"TOGGLE\",\"params\":{\"system\":\"LASER_FENCE\",\"state\":\"off\",\"index\":[3,4]}}]" },
                    new ZoneFloor { goal = Game.Goal.Assassinate, spec = "ASSASSINATE", param = "kill 'Ghostkey' within 60 s for the bonus", layout = "data-vault/vault-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 48), new EnemyEntry("Tick", 10), new EnemyEntry("Leaper", 5), new EnemyEntry("Stalker", 3), new EnemyEntry("Lancer", 2), new EnemyEntry("Mender", 1) }, events = "The marked elite is Ghostkey, a Shade Stalker carrying a stolen core. It flees through the dark bays and laser lattice and summons escorts every 10 s; when revealed it drops a decoy shimmer. The lights go out floor-wide at 20 s (dark=true) until the hero lights both pylons; Ghostkey's eye glints are gold so they are trackable. Lancers on the far racks punish chasing in straight lines.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Ghostkey: follow the gold eyes.\"}},{\"when\":{\"t\":20},\"do\":\"LIGHT\",\"params\":{\"level\":0,\"area\":\"all\"}},{\"when\":{\"t\":20},\"do\":\"HINT\",\"params\":{\"text\":\"Lights out. Light both pylons.\",\"point_to\":\"I\"}},{\"when\":{\"every\":{\"s\":10}},\"do\":\"LIGHT\",\"params\":{\"level\":0,\"area\":\"all\",\"flash\":1.0}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"WATCH THE GOLD EYES IN THE STROBE\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "data-vault/vault-boss", enemies = new EnemyEntry[] { new EnemyEntry("WARDEN-9", 1), new EnemyEntry("Drone", 22), new EnemyEntry("Tick", 8) }, events = "Core Chamber. Four turrets, a grate cross through the middle, laser fences that seal the quadrants in Phase 2, two light pylons and a breaker for Phase 3's blackout.", script = "[{\"when\":{\"start\":true},\"do\":\"TOGGLE\",\"params\":{\"system\":\"LASER_FENCE\",\"state\":\"off\"}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Recapture red turrets. Lure it over the grates.\"}},{\"when\":{\"boss_hp\":0.65},\"do\":\"TOGGLE\",\"params\":{\"system\":\"LASER_FENCE\",\"state\":\"on\",\"warn\":1}},{\"when\":{\"boss_hp\":0.65},\"do\":\"SET\",\"params\":{\"system\":\"LASER_FENCE\",\"on\":5,\"off\":3}},{\"when\":{\"boss_hp\":0.3},\"do\":\"TOGGLE\",\"params\":{\"system\":\"LASER_FENCE\",\"state\":\"on\",\"warn\":1}},{\"when\":{\"boss_hp\":0.3},\"do\":\"SET\",\"params\":{\"system\":\"LASER_FENCE\",\"on\":8,\"off\":2}},{\"when\":{\"boss_hp\":0.3},\"do\":\"HINT\",\"params\":{\"text\":\"GRID LOCK: CROSS ON THE BEAT\"}},{\"when\":{\"boss_hp\":0.3},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Drone\",\"count\":4,\"at\":\"far_S\",\"group\":\"pack\"}}]" },
                },
                mechanics = new[] { "LASER_FENCE", "GRATE", "TURRET", "DARKNESS", "INTERACT" },
                boss = "WARDEN-9", bossBody = "The vault's security frame, now wired with hive tissue. HP 230, slow walk 0.5x, armour front 50%. Phase 1 (100-65%): Suppression. A minigun sweep: a red cone (60 deg, 14 m) telegraphs for 1.0 s and then sweeps for 2 s (10 HP per 0.25 s); server racks and crates block it. Every 15 s it hacks one neutral turret red: a red turret fires at the hero until recaptured (2.5 s), and a recaptured turret prioritises WARDEN-9 and does 3x damage to it. Phase 2 (65-30%): Lockdown. Laser fences seal the arena into four quadrants for 5 s of every 8; WARDEN walks through fences unharmed but takes 6 RH/s on a live grate like any enemy. It chases the hero, so luring it across the central grate cross on the pulse is the damage window. The breaker K shuts the grates off: you get safety, it gets a free floor. Phase 3 (30-0%): Blackout. The lights die (floor-wide DARKNESS) and WARDEN cloaks Stalker-style between sweeps; only its red visor glint shows. Light the two pylons to expose it (+20% damage) and watch for the red cone, which still shows in the dark. Two Stalkers join. Death: it powers down, kneels, the core floats out (bonus Weapon Parts).", bossLook = "Iron Vanguard hero model at 2.0x, tinted gunmetal #2d3238 with a red emissive visor #ff3355 and purple creep veins #b04dff on the limbs (emissive vertex noise); the Vanguard minigun at 2.0x; three thin red line renderers from its back to the nearest turret while hacking. Name banner: WARDEN-9, 'Access denied.'",
                modifiers = new[] { "Lockdown Protocol: every laser fence runs 6 s on, 2 s off.", "Black Site: every floor is dark; flares refill at 2 caches per floor.", "Ghost Protocol: 20% of non-Stalker enemies gain Cloaked.", "Overclocked: grates pulse twice as often and their current travels 1 cell further." },
                stars = new[] { "Clear the zone.", "No revive and under par (4:00).", "Kill Ghostkey within 60 s on the ASSASSINATE floor." }, starBonus = "Kill 40 enemies with electrified grates in one run, without shooting the breaker.", par = 240,
                layoutNotes = new Dictionary<string, string> { {"vault-a", "Server Hall. Four long rack rows with grates in the aisles, a breaker in the north-east corner, turrets at each end of the centre aisle."}, {"vault-b", "Cold Storage. A diagonal staircase of rack blocks with dark bays between them; laser fences gate the bays; six cores, a lift in the south-east, two pylons and a flare cache."}, {"vault-c", "Firewall Ring. A square ring corridor around the core room, relays at three corners behind fences, grates on the inner ring, turrets on the outer ring."}, {"vault-boss", "Core Chamber. Open chamber, grate cross in the middle, laser fences on the quadrant lines, turrets in the four quadrants, pylons and breaker on the edges."} } },
            new SectorDef { id = "seismic-mine", name = "DEEPCUT MINE", num = 10, act = "II", power = 2750, tier = 4, art = "kessler", lat = 2.4f, lon = -5.4f, endless = false,
                blurb = "A collapsing deep-core mine where the swarm swims through rock", pitch = "A collapsing deep-core mine where the swarm swims through rock: read the dust, ride the ore cart through the dark, blow the shaft behind you and face the thing that ate the mine.", signature = "The ground is the enemy. Burrowers (featured) come from below, cave-ins come from above (35 HP rocks that leave rubble for 15 s), and the pits in between are where Shove, shotgun and explosions turn into instant kills. Steel plates are islands where Burrowers cannot surface. From floor 2 the lights are out, so the head lamp, flares and light pylons decide what auto-fire can shoot. Crumbling walkways make every route a one-way decision: you can cross it once, and whatever follows you falls.",
                unlockAny = new string[] { "acid-marsh", "data-vault" }, unlockAfter = "acid-marsh",
                floorTint = C(0x4a3a2c), wallTint = C(0x3b2f26), accent = C(0xb07a3a), sun = C(0xffcf8a), sunIntensity = 0.45f, ambient = C(0x2a2018), fog = C(0x3a2e24), fogStart = 6.0f, fogEnd = 45.0f, particles = Particles.Ash,
                order = new[] { Game.Goal.Purge, Game.Goal.Escort, Game.Goal.Survive, Game.Goal.Detonate, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Purge, spec = "PURGE", param = "3 waves", layout = "seismic-mine/mine-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 36), new EnemyEntry("Burrower", 3), new EnemyEntry("Leaper", 4), new EnemyEntry("Tick", 6), new EnemyEntry("Splitter", 2) }, events = "Lamp Gallery, still lit. Teach pits: wave 1 Drones path round the chasms, and a free Shove card is offered at the start so pit kills happen on the first floor. Teach cave-ins: from wave 2, 2 rock circles every 9 s, and rubble from each lasts 15 s. The crumbling walkway in the middle is shown with a 'it falls behind you' toast the first time it drops a pack.", script = "[{\"when\":{\"start\":true},\"do\":\"DROP\",\"params\":{\"kind\":\"card_offer\",\"card\":\"shove\",\"at\":\"hero\"}},{\"when\":{\"wave\":{\"n\":2,\"at\":\"start\"}},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":2,\"radius\":2,\"interval\":9,\"leaves\":\"rubble\",\"rubble_s\":15,\"skin\":\"rock\"}},{\"when\":{\"enter\":{\"cells\":\"k\"}},\"do\":\"HINT\",\"params\":{\"text\":\"It falls behind you.\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Escort, spec = "ESCORT", param = "ore cart through the dark, 400 HP", layout = "seismic-mine/mine-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 40), new EnemyEntry("Burrower", 3), new EnemyEntry("Leaper", 4), new EnemyEntry("Tick", 8), new EnemyEntry("Spitter", 4) }, events = "Ore Line, lights out. The cart carries the floor's only big light (a 6 m amber lamp on its prow), so pushing it forward also moves your safe vision. Three light pylons along the track light whole bends for good once you stand on them; flare caches at both turns. Burrowers surface under the cart (it takes the eruption) unless the hero stands on a steel plate nearby. A cave-in blocks the track at the halfway point: rubble must be shot (15 RH) before the cart can roll.", script = "[{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0,\"area\":\"all\"}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Push the cart: its lamp is your light. Stand on pylons to light the bends.\"}},{\"when\":{\"progress\":0.5},\"do\":\"STRIKE\",\"params\":{\"mode\":\"fixed\",\"cells\":\":\",\"count\":1,\"radius\":2,\"delay\":1.5,\"aim\":\"ahead_of_cart\",\"leaves\":\"rubble\",\"block_hp\":15,\"blocks_cart\":true,\"skin\":\"rock\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Survive, spec = "SURVIVE", param = "60 s", layout = "seismic-mine/mine-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 48), new EnemyEntry("Burrower", 4), new EnemyEntry("Leaper", 5), new EnemyEntry("Tick", 10), new EnemyEntry("Shrieker", 1), new EnemyEntry("Carapace", 2) }, events = "The Tremor: the gallery is dark this time, and the mine shakes every 15 s (screen shake 0.2, 4 rock circles at once). At 30 s the crumbling walkway collapses by itself and two new pits open where the circles land (they become '_' for the rest of the floor), so the arena loses floor as you fight. Carapaces charge across the gallery: bait them into a pit's edge and shove them in.", script = "[{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0,\"area\":\"all\"}},{\"when\":{\"every\":{\"s\":15}},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":4,\"radius\":2,\"leaves\":\"rubble\",\"rubble_s\":15,\"skin\":\"rock\",\"shake\":0.2}},{\"when\":{\"t\":30},\"do\":\"SET\",\"params\":{\"system\":\"COLLAPSE\",\"collapse\":\"all_k\"}},{\"when\":{\"t\":30},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":2,\"radius\":2,\"leaves\":\"pit\",\"skin\":\"rock\",\"shake\":0.2}}]" },
                    new ZoneFloor { goal = Game.Goal.Detonate, spec = "DETONATE", param = "3 charges, then 25 s to the lift", layout = "seismic-mine/mine-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 52), new EnemyEntry("Burrower", 4), new EnemyEntry("Leaper", 6), new EnemyEntry("Tick", 10), new EnemyEntry("Spitter", 4), new EnemyEntry("Splitter", 3) }, events = "Collapse Shaft. Three charges lie beyond a chasm crossed only by three crumbling bridges. Each bridge carries you once, so the route is: cross one, plant the three charges, and use another bridge to get back to the lift before the blast. Cave-ins every 6 s during the countdown and a Splitter pack comes out of the charge tunnel the moment the last charge is set. If a bridge is gone, a Leaper pounce shows you the jump the swarm can make and you cannot.", script = "[{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0,\"area\":\"all\"}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Each bridge carries you once. Save one for the way back.\"}},{\"when\":{\"done\":{\"kind\":\"charge\",\"count\":3}},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":3,\"radius\":2,\"interval\":6,\"until\":25,\"leaves\":\"rubble\",\"rubble_s\":15,\"skin\":\"rock\"}},{\"when\":{\"done\":{\"kind\":\"charge\",\"count\":3}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Splitter\",\"count\":3,\"at\":\"nearest_S\",\"group\":\"pack\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "seismic-mine/mine-boss", enemies = new EnemyEntry[] { new EnemyEntry("The Maw", 1), new EnemyEntry("Burrower", 3), new EnemyEntry("Drone", 24), new EnemyEntry("Tick", 8) }, events = "The Throat. A dark arena around a central pit with four steel plate islands and two pylons. Rocks fall every time The Maw dives.", script = "[{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0,\"area\":\"all\"}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Light the pylons. Steel plates stop the pull.\"}},{\"when\":{\"boss_hp\":0.25},\"do\":\"HINT\",\"params\":{\"text\":\"Kill the Drones before it eats them.\"}}]" },
                },
                mechanics = new[] { "STRIKE", "COLLAPSE", "PIT", "DARKNESS", "INTERACT" },
                boss = "The Maw", bossBody = "HP 300, only damageable while surfaced. Keeps the doc's three phases and ties each to the mine. Phase 1 (100-60%): Breach and Tremor Lines as in the doc. Every dive brings down 3 rock circles; rubble from them blocks Tremor Lines, so standing behind fresh rubble is safe. Phase 2 (60-25%): Twin Breach plus 3 Burrowers; each breach now cracks the floor around its ring, and the cracked cells become crumbling walkways (k) that fall when stepped on. The arena slowly turns into islands. Pylons light the arena for good; in the dark only the dust rings are visible. Phase 3 (25-0%): Devour, surfacing in the central pit. The pull drags everything toward the pit for 4 s; Drones it eats heal it 2 HP each, but Drones you shove or blow into the pit first are lost to it (no heal). Standing on a steel plate stops the pull, exactly as the doc says, and the plates are the only place the 360 spit cannot reach behind rubble. Win condition feel: the last 25% is a race to clear adds before it can eat them.", bossLook = "Column of 4 stacked Bloater meshes (scaled 1.6, 1.4, 1.2, 1.0) tinted dusty brown #6b5238 with a red emissive mouth ring #ff3a2a (as in the doc); Burrower dust at 3x; a ring of 8 Lancer spikes as teeth inside the mouth. Name banner: THE MAW, 'The mine was never empty.'",
                modifiers = new[] { "Unstable: cave-ins every 5 s on every floor, and rubble lasts 30 s.", "Deep Dark: every floor is dark from floor 1, and flare caches are halved.", "Burrowing Swarm: 15% of Drones travel underground like Burrowers and surface in pairs.", "Rich Seam: every pit kill drops +1 biomass and a Weapon Part (a farming modifier)." },
                stars = new[] { "Clear the zone.", "No revive and under par (4:30).", "Kill 40 enemies by pits or collapsing walkways in one run." }, starBonus = "Finish the DETONATE floor with 10 s or more left on the countdown.", par = 270,
                layoutNotes = new Dictionary<string, string> { {"mine-a", "Lamp Gallery. Irregular chasms on the left, top and right, a crumbling walkway down the middle, two steel-plate islands, two pylons and a flare cache."}, {"mine-b", "Ore Line. A long S-shaped rail from the north-west down to the south: tunnels between rock pillars, pits beside the track, pylons and flare caches at the turns."}, {"mine-c", "Collapse Shaft. Lift and spawn on the north side, a two-cell chasm across the middle with three crumbling bridges, three charges in the south galleries."}, {"mine-boss", "The Throat. Central pit, four steel-plate islands, a ring of crumbling floor in the south, rock pillars and two pylons."} } },
            new SectorDef { id = "quarantine-ward", name = "ST. ASTER QUARANTINE", num = 11, act = "III", power = 3250, tier = 4, art = "hive", lat = -2.4f, lon = 132.1f, endless = false,
                blurb = "A sealed hospital where the infection has started rebuilding the building", pitch = "A sealed hospital where the infection has started rebuilding the building: hive walls grow across corridors, toxic vents breathe on a rhythm, and the healers on the other side keep the swarm alive.", signature = "The building fights back. Toxic vents erupt on a readable 6 s beat (18 HP per tick to you, 4 RH/s to them), so the best tactic is dragging the pack through a vent column on its warning beat. Hive walls block corridors but can be shot down (explosions x3) to open a shortcut or a firing line, and they grow back in 12 s, so routes are temporary. Egg clusters sit in every ward and creep spreads from walls and nests. Menders and Weavers (featured) are the zone's question: the swarm here does not die until you find who is healing it and who is closing the doors.",
                unlockAny = new string[] { "seismic-mine" }, unlockAfter = "seismic-mine",
                floorTint = C(0xcfe0d6), wallTint = C(0xe6ece8), accent = C(0x7fd8a6), sun = C(0xe9fff2), sunIntensity = 0.85f, ambient = C(0x4a6a5a), fog = C(0xb9d6c4), fogStart = 22.0f, fogEnd = 55.0f, particles = Particles.None,
                order = new[] { Game.Goal.Purge, Game.Goal.Escape, Game.Goal.Defend, Game.Goal.Detonate, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Purge, spec = "PURGE", param = "3 waves", layout = "quarantine-ward/ward-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 40), new EnemyEntry("Tick", 8), new EnemyEntry("Leaper", 4), new EnemyEntry("Mender", 2), new EnemyEntry("Carapace", 2), new EnemyEntry("Spitter", 4) }, events = "Triage Hall. Teach vents: four toxic vent columns flank the hall and wave 1 is a pure Drone flood that runs straight through them. Teach Menders: wave 2 brings two Carapaces with a Mender each; a green-tether hint fires on the first heal. Hive walls ring the centre and the first one you shoot regrows in front of you, with a '12 s' timer ring.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Hive walls grow back in 12 s.\"}},{\"when\":{\"wave\":{\"n\":1,\"at\":\"start\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Drone\",\"count\":16,\"at\":\"S\",\"group\":\"pack\"}},{\"when\":{\"wave\":{\"n\":2,\"at\":\"start\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Carapace\",\"count\":2,\"at\":\"far_S\",\"group\":\"pack\"}},{\"when\":{\"wave\":{\"n\":2,\"at\":\"start\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Mender\",\"count\":2,\"at\":\"far_S\",\"group\":\"pack\",\"tether\":\"Carapace\"}},{\"when\":{\"wave\":{\"n\":2,\"at\":\"start\"}},\"do\":\"HINT\",\"params\":{\"text\":\"Green tether = healer. Kill the Mender first.\",\"trigger_on\":\"first_heal\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Escape, spec = "ESCAPE", param = "4 rooms, hack 3 doors", layout = "quarantine-ward/ward-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 44), new EnemyEntry("Tick", 10), new EnemyEntry("Weaver", 2), new EnemyEntry("Leaper", 5), new EnemyEntry("Mender", 2), new EnemyEntry("Spitter", 4) }, events = "Isolation Wing. Four sealed wards. Weavers web every doorway you need to hack. Twist: a hive wall between the first ward and the lift ward is a shortcut. Shoot it down (10 RH) and you can skip the two middle wards, but both of their spawns come with you into the lift ward on top of its own, and the wall regrows behind you. Taking the long route is safer and gives two +35 HP room clears.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Shortcut: shoot the hive wall. The skipped wards follow you.\",\"point_to\":\"m\"}},{\"when\":{\"enter\":{\"cells\":4}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"room_waves\",\"rooms\":[2,3],\"at\":\"S\",\"only_if\":\"rooms_skipped\"}},{\"when\":{\"enter\":{\"cells\":3}},\"do\":\"CUE\",\"params\":{\"id\":\"pa_decon\"}},{\"when\":{\"enter\":{\"cells\":3}},\"do\":\"HINT\",\"params\":{\"text\":\"DECON CYCLE: HACK BETWEEN THE GAS\"}},{\"when\":{\"start\":true},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Weaver\",\"count\":3,\"at\":\"H\",\"group\":\"spread\"}},{\"when\":{\"enter\":{\"cells\":3}},\"do\":\"SET\",\"params\":{\"system\":\"VENT\",\"cycle\":3}},{\"when\":{\"enter\":{\"cells\":3}},\"do\":\"HINT\",\"params\":{\"text\":\"DECONTAMINATION CYCLE: HACK IN THE GAPS\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Defend, spec = "DEFEND", param = "cure synthesiser, 60 s", layout = "quarantine-ward/ward-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 50), new EnemyEntry("Tick", 10), new EnemyEntry("Leaper", 5), new EnemyEntry("Weaver", 2), new EnemyEntry("Mender", 2), new EnemyEntry("Splitter", 3), new EnemyEntry("The Surgeon", 1) }, events = "Cure Lab. The synthesiser G sits inside a ring of hive walls with four gaps. Weavers string webs across the gaps so the hero's way in is closed while enemies walk through. The Surgeon (mini-boss) arrives at 20 s: it re-grows hive walls instantly and tethers to the synthesiser's attackers. Vents ring the lab: luring the attack waves across them on the beat is how you keep the generator alive.", script = "[{\"when\":{\"start\":true},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Weaver\",\"count\":2,\"at\":\"S\",\"group\":\"spread\",\"web\":\"m_gaps\"}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Drag the attackers through the vents on the beat.\"}},{\"when\":{\"t\":20},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"The Surgeon\",\"count\":1,\"at\":\"far_S\"}},{\"when\":{\"t\":20},\"do\":\"HINT\",\"params\":{\"text\":\"THE SURGEON: kill the Drones near it, then drag it through a vent.\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Detonate, spec = "DETONATE", param = "3 charges, then 25 s to the lift", layout = "quarantine-ward/ward-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 56), new EnemyEntry("Tick", 12), new EnemyEntry("Leaper", 6), new EnemyEntry("Mender", 2), new EnemyEntry("Weaver", 2), new EnemyEntry("Stalker", 2), new EnemyEntry("Carapace", 2) }, events = "Sterilise the ward. Three charges sit inside the hive-walled centre and in the east and west wings. On the last plant the vents go to a 3 s cycle (sterilisation gas) and all egg clusters hatch at once (HATCH_ALL). The 25 s run to the lift goes through the vent columns, so the timing of the gas decides your route. Hive walls between you and the lift regrow on a 6 s timer during the countdown.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Plant all three. The gas decides your route out.\"}},{\"when\":{\"done\":{\"kind\":\"charge\",\"count\":3}},\"do\":\"SET\",\"params\":{\"system\":\"VENT\",\"cycle\":3,\"warn\":0.6,\"erupt\":0.9}},{\"when\":{\"done\":{\"kind\":\"charge\",\"count\":3}},\"do\":\"HATCH_ALL\",\"params\":{\"wobble\":3}},{\"when\":{\"done\":{\"kind\":\"charge\",\"count\":3}},\"do\":\"SET\",\"params\":{\"system\":\"HIVE_WALL\",\"regrow\":6,\"for\":25}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "quarantine-ward/ward-boss", enemies = new EnemyEntry[] { new EnemyEntry("Patient Zero", 1), new EnemyEntry("Drone", 24), new EnemyEntry("Mender", 2), new EnemyEntry("Tick", 10) }, events = "Ward Zero. A round ward with creep at the centre, eight toxic vents, four hive wall arcs and egg clusters at the edges.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Creep heals him. Burn it: dash, barrels, Incendiary.\"}},{\"when\":{\"boss_hp\":0.3},\"do\":\"SET\",\"params\":{\"system\":\"SPREAD\",\"skin\":\"creep\",\"tick\":0.83}},{\"when\":{\"boss_hp\":0.3},\"do\":\"SET\",\"params\":{\"system\":\"VENT\",\"cycle\":4}}]" },
                },
                mechanics = new[] { "VENT", "EGGS", "HIVE_WALL", "SPREAD", "INTERACT" },
                boss = "Patient Zero", bossBody = "The first infected, half man and half hive. HP 260, speed 0.7x. Phase 1 (100-65%): Contagion. It walks toward the hero and every 8 s Coughs a toxic cone (8 m, 50 deg, 1.0 s green preview) that leaves creep where it lands. Creep under Patient Zero heals it 2% max HP/s (the zone's SPREAD rule), so scorching the floor it fights on is the first priority: dash through creep, blow barrels, use Incendiary. Phase 2 (65-30%): Quarantine Lines. It slams the floor and hive walls burst up in two straight lines that cut the arena in four for 12 s; each quarter holds egg clusters that hatch in 6 s. Shoot through a wall (explosions x3) to keep the fight in one room, or use the time to clear eggs. Vents in its quarter erupt on its own cycle: a vent hit on Patient Zero stuns it for 1.5 s. Phase 3 (30-0%): Outbreak. It splits: two Menders peel off its back and tether to it; until both die it takes 50% damage. The creep at the centre grows 3x faster and the vents run 4 s cycles. Death: it collapses into a hive wall statue that stays in the arena.", bossLook = "Iron Vanguard hero model at 1.8x, tinted pale sick grey-green #9aa898 with creep veins #b04dff pulsing over the body, a Bloater mesh at 0.8x fused on its back (emissive purple pus), torn hospital sheeting (translucent quad) hanging off one arm. Name banner: PATIENT ZERO, 'It started with him.'",
                modifiers = new[] { "Pandemic: creep spreads at double rate and its cap rises to 60% of walkable cells.", "Overcrowded Ward: every egg cluster hatches 5 Drones instead of 3.", "Field Medics: every pack of 8+ comes with a Mender.", "Sealed Wing: hive walls regrow in 6 s instead of 12 s." },
                stars = new[] { "Clear the zone.", "No revive and under par (4:30).", "Kill every Mender before it heals anything on the DEFEND floor (any Mender heal fails the star)." }, starBonus = "Kill 25 enemies with toxic vents in one run.", par = 270,
                layoutNotes = new Dictionary<string, string> { {"ward-a", "Triage Hall. Bed rows north and south, two hive-wall arcs around the centre, four vent columns, charges in the wings and the centre, lift in the south-east."}, {"ward-b", "Isolation Wing. Four wards in a square loop with blast doors and hacks; a hive wall in the west wall is the shortcut from the first ward to the lift ward."}, {"ward-c", "Cure Lab. Synthesiser in a hive-wall ring with four gaps, vents on the diagonals, creep patches and eggs in the corners."}, {"ward-boss", "Ward Zero. Round ward, creep at the centre, eight vents, four hive wall arcs, egg clusters on the edges, one med station."} } },
            new SectorDef { id = "relay-spire", name = "TYNDALL RELAY SPIRE", num = 12, act = "III", power = 3800, tier = 4, art = "drowned", lat = -7.3f, lon = -90.4f, endless = false,
                blurb = "A comms tower above the clouds in a permanent lightning storm", pitch = "A comms tower above the clouds in a permanent lightning storm: hide under steel from the sky, snipe the snipers, and hold the uplink on dishes where the wind wants to throw you off the edge.", signature = "The sky is a second enemy and cover is the answer to both of them. Lightning STRIKES (35 HP, 12 RH to enemies) fall every 6 s, half on you, and roofs (u) block them, the same roofs that block the Lancers' (featured) lines. Wind gusts every 12 s push everything one way for 3 s: toward the edge pits that is lethal for the swarm and dangerous for you, so you fight upwind and let the gusts clear the deck. Grates carry the storm's current; the breaker turns them off, at the cost of your best killing floor. Stand still and the Lancers and lightning find you; move and the wind decides where you end up.",
                unlockAny = new string[] { "seismic-mine" }, unlockAfter = "seismic-mine",
                floorTint = C(0x5e6670), wallTint = C(0xdfe5ea), accent = C(0xc8321e), sun = C(0x9fb0ff), sunIntensity = 0.6f, ambient = C(0x2a3048), fog = C(0x5a6488), fogStart = 18.0f, fogEnd = 50.0f, particles = Particles.Ash,
                order = new[] { Game.Goal.Purge, Game.Goal.Relay, Game.Goal.Assassinate, Game.Goal.Uplink, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Purge, spec = "PURGE", param = "3 waves", layout = "relay-spire/spire-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 40), new EnemyEntry("Lancer", 3), new EnemyEntry("Tick", 8), new EnemyEntry("Leaper", 4), new EnemyEntry("Splitter", 3) }, events = "Lower Ring. Teach lightning and cover together: the first strike is aimed at the roof you stand under and bounces off it with a 'COVER BLOCKS LIGHTNING' toast. Lancers arrive in wave 2 on the far side of the central housing, so the first trace teaches breaking line of sight. Wind is off on this floor; the pit corners are just for shoves.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"off\"}},{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":3,\"radius\":2,\"interval\":6,\"skin\":\"lightning\"}},{\"when\":{\"t\":4},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":1,\"radius\":2,\"aim\":\"hero\",\"skin\":\"lightning\"}},{\"when\":{\"t\":5.5},\"do\":\"HINT\",\"params\":{\"text\":\"COVER BLOCKS LIGHTNING\"}},{\"when\":{\"wave\":{\"n\":2,\"at\":\"start\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Lancer\",\"count\":3,\"at\":\"far_S\",\"group\":\"spread\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Relay, spec = "RELAY", param = "4 relays in order", layout = "relay-spire/spire-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 46), new EnemyEntry("Lancer", 3), new EnemyEntry("Tick", 10), new EnemyEntry("Leaper", 5), new EnemyEntry("Carapace", 2), new EnemyEntry("Weaver", 1) }, events = "Cable Run. A switchback climb through the cable trays; each relay restores one antenna section. Relay 1 turns off the first grate field; relay 2 brings the wind online (gusts from the west); relay 3 turns the lightning into a storm (strikes every 4 s); relay 4 ends the floor. The breaker sits in the middle: shooting it kills every grate (safer climb) but also the floor's best Drone killer.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"off\"}},{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":3,\"radius\":2,\"interval\":6,\"skin\":\"lightning\"}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":3}},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":2,\"radius\":2,\"interval\":4,\"skin\":\"lightning\"}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":2}},\"do\":\"HINT\",\"params\":{\"text\":\"CABLES LIVE: LURE THEM ACROSS THE GRATES\"}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":2}},\"do\":\"CUE\",\"params\":{\"id\":\"cables_live\"}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":2}},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":2,\"radius\":1.5,\"interval\":4,\"skin\":\"lightning\",\"aim\":\"g\",\"for\":15}}]" },
                    new ZoneFloor { goal = Game.Goal.Assassinate, spec = "ASSASSINATE", param = "kill 'Highwire' within 60 s for the bonus", layout = "relay-spire/spire-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 50), new EnemyEntry("Lancer", 4), new EnemyEntry("Tick", 10), new EnemyEntry("Leaper", 5), new EnemyEntry("Stalker", 2), new EnemyEntry("Highwire", 1) }, events = "The same cable run, now in a gale (west gusts every 10 s). The target is the mini-boss Highwire, a Marksman Lancer that flees up and down the switchbacks, stopping only to fire from roofs. Lightning cannot hit it while it is under a roof, but it can hit you; the chase is about cutting it off at the bends. Escort summons every 10 s are Lancer pairs that cover its retreat.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"dir\":\"E\",\"period\":10}},{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":2,\"radius\":2,\"interval\":8,\"skin\":\"lightning\"}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"Highwire: cut it off at the bends.\"}},{\"when\":{\"every\":{\"s\":15}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Lancer\",\"count\":1,\"at\":\"far_S\",\"group\":\"pack\",\"replaces_default_escort\":true}}]" },
                    new ZoneFloor { goal = Game.Goal.Uplink, spec = "UPLINK", param = "30 s, ring hops between dishes", layout = "relay-spire/spire-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 56), new EnemyEntry("Lancer", 4), new EnemyEntry("Tick", 12), new EnemyEntry("Leaper", 6), new EnemyEntry("Shrieker", 1), new EnemyEntry("Carapace", 2), new EnemyEntry("Mender", 1) }, events = "Summit Dishes. Three landing dishes on the summit, split by the central shaft and two jump-pad pairs. The uplink ring hops between dishes every 10 s, and the dishes have no roofs: lightning every 5 s targets the ring. Wind gusts alternate east and west, pushing toward the edge pits on both sides. A Shrieker hides behind the north housings; a Mender keeps two Carapaces alive in the ring.", script = "[{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":3,\"radius\":2,\"interval\":5,\"aim\":\"Z_ring\",\"skin\":\"lightning\"}},{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"dir\":[\"E\",\"W\"],\"period\":12}},{\"when\":{\"start\":true},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Shrieker\",\"count\":1,\"at\":\"S\",\"index\":[1,2],\"group\":\"pack\"}},{\"when\":{\"start\":true},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Carapace\",\"count\":2,\"at\":\"Z\",\"group\":\"pack\"}},{\"when\":{\"start\":true},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Mender\",\"count\":1,\"at\":\"Z\",\"group\":\"pack\",\"tether\":\"Carapace\"}},{\"when\":{\"t\":15},\"do\":\"FOG\",\"params\":{\"end_m\":12,\"density_mult\":3,\"for\":15}},{\"when\":{\"t\":15},\"do\":\"HINT\",\"params\":{\"text\":\"CLOUD BANK: WATCH THE GUST ARROW\"}},{\"when\":{\"t\":15},\"do\":\"CUE\",\"params\":{\"id\":\"cloud_bank\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "relay-spire/spire-boss", enemies = new EnemyEntry[] { new EnemyEntry("The Arc Matron", 1), new EnemyEntry("Lancer", 2), new EnemyEntry("Drone", 24), new EnemyEntry("Tick", 10) }, events = "Crown Platform. Four antenna pylons, a ring of grates, four roofs and pit corners. Wind on, lightning every 6 s, and both are her weapons until you turn them against her.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"dir\":[\"N\",\"E\",\"S\",\"W\"],\"period\":12}},{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":3,\"radius\":2,\"interval\":6,\"skin\":\"lightning\"}},{\"when\":{\"boss_hp\":0.65},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":3,\"radius\":2,\"interval\":4,\"skin\":\"lightning\",\"aim\":\"boss\"}},{\"when\":{\"boss_hp\":0.3},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"dir\":[\"N\",\"E\",\"S\",\"W\"],\"period\":8}},{\"when\":{\"boss_hp\":0.3},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":3,\"radius\":2,\"interval\":3,\"skin\":\"lightning\"}}]" },
                },
                mechanics = new[] { "STRIKE", "COVER", "WIND", "GRATE", "INTERACT", "JUMP_PAD", "PIT" },
                boss = "The Arc Matron", bossBody = "A queen Weaver that has wrapped the spire's crown in her web and feeds on the storm. HP 280. Phase 1 (100-65%): Charged Web. She strings electrified strands between the four antenna pylons (Matron Weaver rule: 8 damage on touch), 3 at a time; each strand lasts 12 s. Lightning that hits a strand arcs along it (15 HP to anything touching it, enemies included). Shoot strands (3 HP) or let the wind snap them (gusts break strands parallel to the gust). Phase 2 (65-30%): Lightning Rod. She climbs a pylon (2 s) and becomes the storm's target: lightning every 4 s, but each strike near her heals her 10 HP unless the pylon's base grate is off. Every pylon has a grate under it; shooting the breaker drops all four, and a Matron on a dead pylon takes the strike instead (12 RH and a 2 s fall stun). She also calls Lancers from the edges. Phase 3 (30-0%): Storm Cradle. She comes down and spins a web dome over the roofs, cutting the hero off from cover; gusts every 8 s push toward the pit corners and lightning falls every 3 s. Burn or shoot your way into a roof, fight from under it, and let her chase you through the open where the storm hits her too. Death: the storm breaks, sunlight floods the platform for the reward screen.", bossLook = "Leaper model at 2.8x (the Weaver recipe), tinted ivory #ece4d0 with dark purple joints and a cyan #5fd8ff emissive abdomen that crackles (spark particles) whenever lightning lands within 6 m; strands are the Weaver tracer cylinder in cyan. Name banner: THE ARC MATRON, 'She weaves the storm.'",
                modifiers = new[] { "Superstorm: lightning every 3 s, and one in four strikes chains to the nearest unit within 4 m.", "Hurricane: gusts every 8 s from a random direction (2 s warning still applies).", "Sniper Nest: Lancer max alive +2, and every Lancer is a Marksman (3-spine fan).", "Torn Roofs: half the roofs are missing on every floor." },
                stars = new[] { "Clear the zone.", "No revive and under par (4:30).", "Let lightning kill 30 enemies in one run." }, starBonus = "Kill Highwire within 60 s without shooting the breaker.", par = 270,
                layoutNotes = new Dictionary<string, string> { {"spire-a", "Lower Ring. A deck around the central antenna housing, four roofs on the sides, two pairs of housings, pit corners at the edge."}, {"spire-b", "Cable Run. A switchback climb from the north-west, through cable trays and grate fields, to the south; relays at each turn, breaker in the middle."}, {"spire-c", "Summit Dishes. Two dishes split by a central shaft and joined by two jump-pad pairs, a third dish on the south deck, roofs between them, edge pits east and west."}, {"spire-boss", "Crown Platform. Four antenna pylons in a square with grates between them, four roofs, pit corners, breaker on the east edge."} } },
            new SectorDef { id = "skyhook", name = "SKYHOOK ANCHOR", num = 13, act = "III", power = 4450, tier = 5, art = "kessler", lat = -12.3f, lon = 47.1f, endless = false,
                blurb = "The ground station of a space elevator, bolted to a mesa over a 2 km drop", pitch = "The ground station of a space elevator, bolted to a mesa over a 2 km drop: every gust of wind is a weapon, and the swarm has never learned to hold on.", signature = "Positioning is your best gun. Every 12 s a gust shoves everything 4 m/s one way; you can dash through it or hide in a block's wind shadow, the swarm cannot. Fight with the void downwind of the pack and a single gust clears the screen (full biomass for every fall). Crumbling walkways mean every route you take closes behind you, which also drops whatever was chasing you, and jump pads are the only routes that never break. Leapers are the counter-threat: they pounce across 3-cell gaps, so the safe island is never safe for long.",
                unlockAny = new string[] { "quarantine-ward" }, unlockAfter = "quarantine-ward",
                floorTint = C(0x8a9299), wallTint = C(0x5c646c), accent = C(0x4fd2ff), sun = C(0xffe9c7), sunIntensity = 1.3f, ambient = C(0x8fb3d9), fog = C(0xdfe8f2), fogStart = 40.0f, fogEnd = 120.0f, particles = Particles.None,
                order = new[] { Game.Goal.Purge, Game.Goal.Relay, Game.Goal.Escort, Game.Goal.Uplink, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Purge, spec = "PURGE", param = "3 waves", layout = "skyhook/skyhook-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 48), new EnemyEntry("Leaper", 6), new EnemyEntry("Spitter", 4), new EnemyEntry("Tick", 10) }, events = "Teach. The first gust fires 8 s in with a big HUD arrow and the hint 'GUSTS PUSH THE SWARM. STAND BEHIND BLOCKS.' Wave 2 comes up the north bridges in a single column, timed so a gust lands as they cross (scripted 'first void kill' moment, 10+ Drones off the edge). Wave 3 Leapers pounce the pit belts. The crumbling walkways crack under the hero's feet the first time with a slow-motion 0.3 s beat.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"dir\":\"E\",\"period\":12,\"first\":8}},{\"when\":{\"t\":8},\"do\":\"HINT\",\"params\":{\"text\":\"GUSTS PUSH THE SWARM. STAND BEHIND BLOCKS.\",\"arrow\":true}},{\"when\":{\"wave\":{\"n\":2,\"at\":\"start\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Drone\",\"count\":12,\"at\":\"far_S\",\"group\":\"pack\",\"route\":\"north bridges, single column\"}},{\"when\":{\"wave\":{\"n\":2,\"at\":\"start\"}},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"dir\":\"E\",\"period\":12,\"next_gust_in\":6}},{\"when\":{\"wave\":{\"n\":3,\"at\":\"start\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Leaper\",\"count\":6,\"at\":\"S\",\"group\":\"spread\"}},{\"when\":{\"enter\":{\"cells\":\"k\"}},\"do\":\"CUE\",\"params\":{\"id\":\"first_crumble_slowmo\",\"slowmo_s\":0.3,\"once\":true}}]" },
                    new ZoneFloor { goal = Game.Goal.Relay, spec = "RELAY", param = "3 cable clamps, in order", layout = "skyhook/skyhook-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 44), new EnemyEntry("Leaper", 8), new EnemyEntry("Weaver", 2), new EnemyEntry("Lancer", 2), new EnemyEntry("Tick", 12) }, events = "Twist. Each clamp terminal (R) is on a different island. Clamp 1 (north-west) is only reachable by jump pad from the central island; clamp 2 (north-east) by a crumbling walkway that falls behind you; clamp 3 (south-east) by the long south walkway. Each clamp completed swings the wind round 90 degrees (HUD compass) and fires a gust immediately. Weavers string webs across the walkways (a webbed walkway is a trap: stopped on a crumbling cell). Lancers on the far islands shoot across the void: no cover but anchor blocks.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"dir\":\"N\",\"period\":12}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"CLAMP 1: TAKE THE JUMP PAD FROM THE HUB\"}},{\"when\":{\"done\":{\"kind\":\"relay\"}},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"rotate_deg\":90,\"gust_now\":true}}]" },
                    new ZoneFloor { goal = Game.Goal.Escort, spec = "ESCORT", param = "climber cart along the rail spine", layout = "skyhook/skyhook-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 50), new EnemyEntry("Leaper", 8), new EnemyEntry("Carapace", 3), new EnemyEntry("Shrieker", 2), new EnemyEntry("Tick", 12), new EnemyEntry("Gale Ravager", 1) }, events = "Test. The cargo cart rides a rail that crosses the void on a 1-cell bridge with no railings. Gusts push enemies off the bridge but also push the hero: stand downwind of the cart. Carapace charges along the bridge can be sidestepped so they fly off the end. At 50% track, the Gale Ravager (mini-boss) lands on the east deck and charges the cart.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"dir\":\"S\",\"period\":12}},{\"when\":{\"progress\":0.5},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Gale Ravager\",\"count\":1,\"at\":\"far_S\",\"area\":\"east deck\",\"target\":\"cart\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Uplink, spec = "UPLINK", param = "ring hops across 4 islands, 30 s", layout = "skyhook/skyhook-d", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 56), new EnemyEntry("Leaper", 10), new EnemyEntry("Splitter", 4), new EnemyEntry("Lancer", 2), new EnemyEntry("Tick", 14), new EnemyEntry("Mender", 2) }, events = "Climax. The upload ring jumps between four corner islands and the central spine every 10 s. The crumbling walkways are the fast way to the next ring and fall after use; the hazard-striped bridges are slow but permanent; one jump pad pair links the diagonal. Gusts every 9 s on this floor (storm front). At 20 s the climber car breaks loose high above and three STRIKE containers fall on the spine (red circles, leave crates as new wind shadows).", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"dir\":\"W\",\"period\":9}},{\"when\":{\"t\":20},\"do\":\"STRIKE\",\"params\":{\"mode\":\"fixed\",\"count\":3,\"cells\":\"spine (cols 9-12, rows 6-8)\",\"radius\":2,\"delay\":1.5,\"skin\":\"container\",\"leaves\":\"C\"}},{\"when\":{\"t\":20},\"do\":\"CUE\",\"params\":{\"id\":\"climber_snap\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "skyhook/skyhook-boss", enemies = new EnemyEntry[] { new EnemyEntry("Cloudbreaker", 1), new EnemyEntry("Drone", 24), new EnemyEntry("Leaper", 4), new EnemyEntry("Tick", 8) }, events = "The Tether Crown: an outer ring around the elevator shaft, joined to the inner ring by four crumbling spokes and one jump pad pair. Cloudbreaker pounces between rings; its landings crack spokes. Gusts every 12 s, and in phase 3 the boss calls them.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"dir\":\"E\",\"period\":12}},{\"when\":{\"boss_hp\":0.3},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"period\":7,\"dir\":\"toward_nearest_pit_from_hero\",\"roar_warn\":1.0}}]" },
                },
                mechanics = new[] { "WIND", "PIT", "COLLAPSE", "JUMP_PAD", "INTERACT" },
                boss = "Cloudbreaker", bossBody = "A giant alpha Leaper that has lived on the tether, HP 280. Phase 1 (100-60%): Sky Pounce: picks a landing spot on the hero's ring (red arrow plus a 3 m red landing circle, 1.2 s), lands for 25 damage and a 4 m shove, and any crumbling cell under the circle falls. Between pounces it stalks at 0.6x and swipes (cone, 0.7 s, 18 damage). Phase 2 (60-30%): Cable Snap: it tears a tether cable; a yellow line telegraph crosses the arena (1.0 s) and a whipping cable sweeps along it (30 damage, shoves enemies into pits too). Lays 2 egg-less Leaper pups per pounce. Phase 3 (30-0%): Stormcaller: it roars before every gust, gusts every 7 s and the boss chooses the direction, always toward the nearest pit from the hero; it pounces only across pits. Counterplay: the boss can't be killed by falling, but a gust or a jump pad landing shove that catches it within 1 m of a pit lip makes it hang on (LEDGE, 4 s, x2 damage, once per 15 s). Take the jump pad when it commits to a pounce on your ring and it lands on nothing but crumbling cells.", bossLook = "Leaper model at 3.0x, storm grey #6f7a86 with white streak tint on the back and cyan emissive eyes #4fd2ff; the cable is a stretched cylinder (tether material) with the tracer trail.",
                modifiers = new[] { "Jet Stream: gusts every 7 s and 5 m/s.", "Rotten Decking: every '.' cell next to a pit is a crumbling cell.", "Pouncers: +50% Leapers, and Leapers pounce gaps up to 4 cells.", "Ion Storm: lightning STRIKE every 9 s; anchor blocks act as lightning rods (strikes within 3 cells of a block hit the block instead)." },
                stars = new[] { "Clear the zone.", "No revive and under par (5:00).", "Beat Cloudbreaker after making it hang off a ledge three times." }, starBonus = "Kill 60 enemies with falls in one run (void kills count across all floors).", par = 300,
                layoutNotes = new Dictionary<string, string> { {"skyhook-a", "Anchor Ring. North and south decks, two pit belts crossed by crumbling walkways and a railed central bridge, the anchor block in the middle as the wind shadow everyone fights over."}, {"skyhook-b", "Clamp Islands. Five islands: south-west start, central hub, north-west clamp by jump pad only, north-east clamp by a crumbling walkway, south-east clamp by the long crumbling bridge and a railed descent from the north-east."}, {"skyhook-c", "Cargo Spine. The cart rail snakes from the west deck across a 1-cell bridge over the central chasm to the east deck. A jump pad pair at the south crosses back."}, {"skyhook-d", "Shear Deck. Four corner islands and a central spine; each island has a crumbling fast bridge and a striped permanent one. One jump pad pair links south-west to north-east."}, {"skyhook-boss", "Tether Crown. Outer ring, crumbling spokes, inner ring around the open tether shaft in the centre; one jump pad pair from the north outer ring to the inner ring."} } },
            new SectorDef { id = "dreadnought", name = "WRECK OF THE VALIANT", num = 14, act = "III", power = 5200, tier = 5, art = "cryo", lat = -17.4f, lon = -175.4f, endless = false,
                blurb = "A fleet carrier that fell out of orbit and broke its back on the plateau, still burning, still tilting, its guns still looking for targets", pitch = "A fleet carrier that fell out of orbit and broke its back on the plateau, still burning, still tilting, its guns still looking for targets.", signature = "The deck slopes, so everything drifts downhill at 1.2 m/s: you, the swarm, and the barrels. Fighting uphill is slow and safe, fighting downhill is fast and dangerous, and a barrel kicked loose at the top rolls into the pack below and explodes. Fires spread across carpets and crates and can be used to wall off a flank. Point-defence turrets still work: capture one and the swarm turns on it, which is a breather you have to place well. The finale is a reactor fire chasing you down the engine spine.",
                unlockAny = new string[] { "relay-spire" }, unlockAfter = "relay-spire",
                floorTint = C(0x4a4f55), wallTint = C(0x3b4047), accent = C(0xffb347), sun = C(0xd8dde6), sunIntensity = 0.8f, ambient = C(0xa0a8b8), fog = C(0x3a3a3f), fogStart = 40.0f, fogEnd = 120.0f, particles = Particles.Rain,
                order = new[] { Game.Goal.Purge, Game.Goal.Salvage, Game.Goal.Defend, Game.Goal.Outrun, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Purge, spec = "PURGE", param = "3 waves", layout = "dreadnought/valiant-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 50), new EnemyEntry("Leaper", 6), new EnemyEntry("Bloater", 3), new EnemyEntry("Spitter", 4), new EnemyEntry("Tick", 10) }, events = "Teach. Hangar deck tilted east. Barrels line the uphill west wall: the first time the hero shoots near one, the hint 'BARRELS ROLL DOWNHILL' shows and it bowls into wave 1. Two turrets are live. Wave 3 spawns uphill (Bloaters roll faster downhill, 0.7x).", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"DRIFT\",\"state\":\"on\",\"dir\":\"E\"}},{\"when\":{\"start\":true},\"do\":\"CAPTURE\",\"params\":{\"target\":\"all\",\"owner\":\"neutral\"}},{\"when\":{\"wave\":{\"n\":1,\"at\":\"start\"}},\"do\":\"HINT\",\"params\":{\"text\":\"BARRELS ROLL DOWNHILL\",\"show_when\":\"hero first shoots within 4 m of a barrel\"}},{\"when\":{\"wave\":{\"n\":3,\"at\":\"start\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Bloater\",\"count\":3,\"at\":\"S\",\"side\":\"W (uphill)\",\"group\":\"spread\"}},{\"when\":{\"wave\":{\"n\":3,\"at\":\"start\"}},\"do\":\"SET\",\"params\":{\"system\":\"DRIFT\",\"bloater_speed_downhill\":0.7}}]" },
                    new ZoneFloor { goal = Game.Goal.Salvage, spec = "SALVAGE", param = "5 flight recorders", layout = "dreadnought/valiant-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 46), new EnemyEntry("Leaper", 6), new EnemyEntry("Carapace", 3), new EnemyEntry("Weaver", 2), new EnemyEntry("Stalker", 2), new EnemyEntry("Tick", 12) }, events = "Twist. Crew compartments: each recorder ($) sits in a different room. Fires (f) spread through the compartments over the floor (SPREAD fire on carpet), so the order you loot them matters: the burning rooms first. Each pickup's ambush arrives through the downhill doorway. Carapace charges downhill are 30% faster and cannot stop at the doorway: bait them into bulkheads.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"DRIFT\",\"state\":\"on\",\"dir\":\"E\"}},{\"when\":{\"start\":true},\"do\":\"SEED\",\"params\":{\"skin\":\"fire\",\"at\":\"f\",\"tick\":1.5}},{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"DRIFT\",\"carapace_charge_downhill_mult\":1.3,\"carapace_can_stop_at_door\":false}},{\"when\":{\"done\":{\"kind\":\"pickup\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Drone\",\"count\":5,\"at\":\"door\",\"side\":\"downhill\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Defend, spec = "DEFEND", param = "fire-control core, 60 s", layout = "dreadnought/valiant-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 60), new EnemyEntry("Leaper", 8), new EnemyEntry("Bloater", 3), new EnemyEntry("Shrieker", 2), new EnemyEntry("Lancer", 2), new EnemyEntry("Tick", 12), new EnemyEntry("Deck Crusher", 1) }, events = "Test. Protect the fire-control core (G) on its railed dais while six point-defence turrets ring the deck. Captured turrets take the heat off the core (enemies near a live turret attack it 50% of the time), so the floor is about rotating captures. Deck Crusher (mini-boss) arrives at 30 s from uphill and charges the core.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"DRIFT\",\"state\":\"on\",\"dir\":\"S\"}},{\"when\":{\"start\":true},\"do\":\"CAPTURE\",\"params\":{\"target\":\"all\",\"owner\":\"neutral\"}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"CAPTURE TURRETS TO DRAW THE SWARM OFF THE CORE\"}},{\"when\":{\"t\":30},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Deck Crusher\",\"count\":1,\"at\":\"far_S\",\"side\":\"N (uphill)\",\"target\":\"G\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Outrun, spec = "OUTRUN", param = "reactor fire front from the west", layout = "dreadnought/valiant-d", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 62), new EnemyEntry("Leaper", 8), new EnemyEntry("Splitter", 4), new EnemyEntry("Spitter", 4), new EnemyEntry("Tick", 16) }, events = "Climax. The reactor fire FRONT starts at the west wall and sweeps east at 1.3 m/s; the deck now tilts east as well (it pushes you toward the lift, so the danger is overrunning into packs). Three bulkhead terminals (R) pause it 4 s each. Enemies spawn ahead from the east. Barrels in the corridor explode when the front reaches them: stay ahead of the chain.", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"DRIFT\",\"state\":\"on\",\"dir\":\"E\"}},{\"when\":{\"start\":true},\"do\":\"FRONT\",\"params\":{\"skin\":\"fire\",\"dir\":\"E\",\"speed\":1.3,\"countdown\":5,\"state\":\"start\",\"from\":\"W wall\"}},{\"when\":{\"done\":{\"kind\":\"terminal\"}},\"do\":\"FRONT\",\"params\":{\"state\":\"pause\",\"for\":4}},{\"when\":{\"every\":{\"s\":8}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Drone\",\"count\":4,\"at\":\"ahead\",\"side\":\"E\"}},{\"when\":{\"t\":13},\"do\":\"HINT\",\"params\":{\"text\":\"THE KEEL IS SHIFTING\",\"style\":\"warning\"}},{\"when\":{\"t\":15},\"do\":\"WEATHER\",\"params\":{\"system\":\"DRIFT\",\"state\":\"on\",\"dir\":\"W\"}},{\"when\":{\"t\":15},\"do\":\"CUE\",\"params\":{\"id\":\"hull_groan\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "dreadnought/valiant-boss", enemies = new EnemyEntry[] { new EnemyEntry("Fallen Vanguard", 1), new EnemyEntry("Drone", 26), new EnemyEntry("Leaper", 4), new EnemyEntry("Tick", 10), new EnemyEntry("Mender", 1) }, events = "The bridge. The boss stands on the raised command deck behind railings. Four bridge turrets: whoever captures them last owns them (in phase 3 the boss captures them too).", script = "[{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"DRIFT\",\"state\":\"on\",\"dir\":\"S\"}},{\"when\":{\"start\":true},\"do\":\"CAPTURE\",\"params\":{\"target\":\"all\",\"owner\":\"neutral\"}},{\"when\":{\"boss_hp\":0.35},\"do\":\"CAPTURE\",\"params\":{\"target\":\"all\",\"owner\":\"enemy\",\"radius_m\":10,\"from\":\"@\"}},{\"when\":{\"boss_hp\":0.35},\"do\":\"SEED\",\"params\":{\"skin\":\"fire\",\"at\":\"p\",\"count\":4,\"tick\":1.5}}]" },
                },
                mechanics = new[] { "DRIFT", "SPREAD", "TURRET", "FRONT", "INTERACT" },
                boss = "Fallen Vanguard", bossBody = "The Valiant's last marine, infested: a hero-scale gunner, HP 260. Phase 1 (100-65%): Suppression: walks the command deck firing minigun bursts in a 40 deg red cone (0.8 s telegraph, 3 s burst, 6 damage per hit); breaks off to toss a barrel downhill every 10 s. Phase 2 (65-35%): Barrage, the hero's own skill turned on you: plants (stomp ring), 3 s overdrive cone with knockback, and the knockback plus the drift pushes you downhill into the fire cells at the bottom of the bridge. Break line of sight behind crates or dash across the cone. Phase 3 (35-0%): Hive Override: the boss captures every turret within 10 m (they go red and fire at you) and sets fire to the upper bridge; recapturing a turret also makes it fire at the boss (x3 damage, the only way to strip his 50% damage reduction in this phase). Counterplay throughout: barrels rolled from the uphill wall deal triple damage to him; attack from the side of the cone, never from below.", bossLook = "The Iron Vanguard hero model at 1.6x, armour tinted infested purple #5a2a6e with creep veins (the creep emissive #b04dff) on the shoulders, red-violet visor; minigun as built, its muzzle flash recoloured violet.",
                modifiers = new[] { "Hard Tilt: drift 2.0 m/s and barrels respawn at the top wall every 20 s.", "Inferno: every floor starts with twice the fire cells and fire spreads 30% faster.", "Rogue Defences: unowned turrets fire at the hero after 10 s idle until captured.", "Armoured Boarders: 20% of spawns are Armoured (enemies doc modifier)." },
                stars = new[] { "Clear the zone.", "No revive and under par (5:00).", "Finish the OUTRUN floor without the fire front ever touching you, and win the boss fight after recapturing every turret." }, starBonus = "Kill 30 enemies with rolling barrels in one run.", par = 300,
                layoutNotes = new Dictionary<string, string> { {"valiant-a", "Hangar Deck. Drift east. Parked fighters as blocks, barrels on the uphill west wall, two point-defence turrets."}, {"valiant-b", "Crew Compartments. A grid of rooms with bulkheads and doorways, one recorder per room, the lift in the middle-east room."}, {"valiant-c", "Point-Defence Deck. A railed dais around the fire-control core, six turrets around the deck, crates as charge bait."}, {"valiant-d", "Engine Spine. A long west-to-east corridor broken by engine blocks, three bulkhead terminals and the lift at the east end."}, {"valiant-boss", "The Bridge. Raised command deck at the north behind railings (entry in the middle), four turrets, fire at the low south end."} } },
            new SectorDef { id = "meltdown", name = "HALVORSEN REACTOR", num = 15, act = "III", power = 6050, tier = 6, art = "cryo", lat = -22.7f, lon = -37.9f, endless = false,
                blurb = "The colony's fusion plant, ninety seconds from going critical and full of things that like the heat", pitch = "The colony's fusion plant, ninety seconds from going critical and full of things that like the heat: turn the valves, save the pumps, scram the core and get out.", signature = "Act III's exam. Radiation zones are the shortest routes and the swarm grows stronger (+20% damage) standing in them, so you dart through and never fight inside. Steam vents on a two-group rhythm are kill columns if you lure the pack through on the warning beat. Valve and pump terminals are the floor's real objectives and enemies know it: every interaction is a stand-your-ground moment while auto-fire carries you. The zone ends in a scram (plant charges on the control rods, run) and a fight with a thing that eats radiation.",
                unlockAny = new string[] { "skyhook", "dreadnought" }, unlockAfter = "skyhook",
                floorTint = C(0xb8b5ad), wallTint = C(0x9aa0a6), accent = C(0x5f6670), sun = C(0xf2f6ff), sunIntensity = 1.0f, ambient = C(0x7f8a92), fog = C(0xe6eef2), fogStart = 30.0f, fogEnd = 70.0f, particles = Particles.None,
                order = new[] { Game.Goal.Relay, Game.Goal.Hunt, Game.Goal.Defend, Game.Goal.Outrun, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Relay, spec = "RELAY", param = "3 purge valves, in order", layout = "meltdown/halvorsen-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 52), new EnemyEntry("Leaper", 6), new EnemyEntry("Spitter", 4), new EnemyEntry("Burrower", 2), new EnemyEntry("Tick", 10) }, events = "Teach. Turbine hall full of radiation patches and vents. Each valve (R) purges the radiation in its quarter of the room (q cells fade out over 3 s) and fires every vent at once as a steam burst that kills anything in it. Valve 2 sits inside a radiation patch: the RAD meter tutorial.", script = "[{\"when\":{\"start\":true},\"do\":\"CUE\",\"params\":{\"id\":\"core_temp\",\"stage\":1}},{\"when\":{\"done\":{\"kind\":\"relay\"}},\"do\":\"TOGGLE\",\"params\":{\"system\":\"RADIATION\",\"state\":\"off\",\"area\":\"quarter of the completed valve\",\"warn\":0,\"fade\":3}},{\"when\":{\"done\":{\"kind\":\"relay\"}},\"do\":\"SET\",\"params\":{\"system\":\"VENT\",\"erupt_all_now\":true,\"for\":1.5}},{\"when\":{\"enter\":{\"cells\":\"q\"}},\"do\":\"HINT\",\"params\":{\"text\":\"RADIATION: DART THROUGH, DON'T FIGHT IN IT\",\"once\":true}}]" },
                    new ZoneFloor { goal = Game.Goal.Hunt, spec = "HUNT", param = "3 nests", layout = "meltdown/halvorsen-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 54), new EnemyEntry("Leaper", 6), new EnemyEntry("Bloater", 3), new EnemyEntry("Mender", 2), new EnemyEntry("Spore Pod", 2), new EnemyEntry("Stalker", 2), new EnemyEntry("Tick", 10) }, events = "Twist. The spent-fuel pool: one nest sits on the cooling pool, two in irradiated corners. Enemies spawned from those nests start irradiated (glowing, +20% damage, leave a 1-cell q trail for 4 s). Menders tether the nests. The vents here are tied to the pool and fire every 4 s.", script = "[{\"when\":{\"start\":true},\"do\":\"CUE\",\"params\":{\"id\":\"core_temp\",\"stage\":2}},{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"VENT\",\"cycle\":4}},{\"when\":{\"done\":{\"kind\":\"nest\",\"index\":1}},\"do\":\"HINT\",\"params\":{\"text\":\"COOLANT LOST: RAD IS CLIMBING. FINISH IT.\"}},{\"when\":{\"done\":{\"kind\":\"nest\",\"index\":1}},\"do\":\"CUE\",\"params\":{\"id\":\"core_temp_spike\"}},{\"when\":{\"done\":{\"kind\":\"nest\",\"index\":1}},\"do\":\"SET\",\"params\":{\"system\":\"VENT\",\"cycle\":2}},{\"when\":{\"done\":{\"kind\":\"nest\",\"index\":1}},\"do\":\"FOG\",\"params\":{\"density\":0.5,\"color\":\"#7dff6a\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Defend, spec = "DEFEND", param = "coolant pump, 60 s", layout = "meltdown/halvorsen-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 64), new EnemyEntry("Leaper", 8), new EnemyEntry("Carapace", 3), new EnemyEntry("Splitter", 4), new EnemyEntry("Shrieker", 2), new EnemyEntry("Tick", 14), new EnemyEntry("Gravid Bloater", 1) }, events = "Test. Keep the main coolant pump (G) alive for 60 s inside its railed pit. Two valve terminals (R) each vent the pump's steam for 6 s (cooldown 15 s): every vent on the floor erupts and the pump is immune for the eruption. The irradiated Gravid Bloater (mini-boss) arrives at 25 s and walks straight for the pump.", script = "[{\"when\":{\"start\":true},\"do\":\"CUE\",\"params\":{\"id\":\"core_temp\",\"stage\":3}},{\"when\":{\"t\":25},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Gravid Bloater\",\"count\":1,\"at\":\"far_S\",\"variant\":\"Hot Gravid (irradiated)\",\"target\":\"G\"}},{\"when\":{\"progress\":0.5},\"do\":\"HINT\",\"params\":{\"text\":\"COOLANT LEAK: HOLD THE PUMP IN THE RAD\"}},{\"when\":{\"done\":{\"kind\":\"terminal\"}},\"do\":\"SET\",\"params\":{\"system\":\"VENT\",\"cycle\":2}},{\"when\":{\"progress\":0.5},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":3,\"radius\":1.5,\"interval\":3,\"skin\":\"radiation\",\"aim\":\"G\",\"for\":15}}]" },
                    new ZoneFloor { goal = Game.Goal.Outrun, spec = "OUTRUN", param = "coolant flood from the south wall, 1.1 m/s", layout = "meltdown/halvorsen-d", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 66), new EnemyEntry("Leaper", 8), new EnemyEntry("Lancer", 2), new EnemyEntry("Spitter", 4), new EnemyEntry("Weaver", 2), new EnemyEntry("Tick", 16) }, events = "Climax. Scram the core: plant charges on the four control rods (!), three of them inside radiation (plant time 3 s, which costs about 40% RAD each). On the last plant the 25 s countdown starts and the vents switch to 'overpressure' (eruptions every 3 s). Weavers web the route to the lift during the countdown.", script = "[{\"when\":{\"start\":true},\"do\":\"CUE\",\"params\":{\"id\":\"core_temp\",\"stage\":4}},{\"when\":{\"start\":true},\"do\":\"FRONT\",\"params\":{\"skin\":\"flood\",\"dir\":\"N\",\"speed\":1.1,\"countdown\":5,\"state\":\"start\"}},{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"VENT\",\"cycle\":3}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"SCRAM FAILED: OUTRUN THE COOLANT. SLAM THE DAMPERS TO STALL IT.\"}},{\"when\":{\"t\":12},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Weaver\",\"count\":2,\"at\":\"ahead\"}},{\"when\":{\"every\":{\"s\":8}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Drone\",\"count\":5,\"at\":\"ahead\"}},{\"when\":{\"t\":5},\"do\":\"FOG\",\"params\":{\"density\":0.35,\"color\":\"#7dff6a\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "meltdown/halvorsen-boss", enemies = new EnemyEntry[] { new EnemyEntry("Core Behemoth", 1), new EnemyEntry("Drone", 28), new EnemyEntry("Leaper", 4), new EnemyEntry("Tick", 10), new EnemyEntry("Mender", 2) }, events = "The core chamber: the boss walks a ring of radiation around the reactor, four valves (R) at the corners, vents at the cardinal points. Phase 3 brings a reactor fire FRONT.", script = "[{\"when\":{\"start\":true},\"do\":\"CUE\",\"params\":{\"id\":\"core_temp\",\"stage\":5}},{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"INTERACT\",\"terminal\":\"valve\",\"effect\":\"purge q in its quarter\",\"cooldown\":20}},{\"when\":{\"boss_hp\":0.35},\"do\":\"FRONT\",\"params\":{\"skin\":\"fire\",\"dir\":\"S\",\"speed\":1.0,\"countdown\":3,\"state\":\"start\",\"stop_at\":\"reactor block (row 5)\"}},{\"when\":{\"done\":{\"kind\":\"terminal\"}},\"do\":\"FRONT\",\"params\":{\"state\":\"pause\",\"for\":4}}]" },
                },
                mechanics = new[] { "RADIATION", "VENT", "INTERACT", "FRONT", "NEST", "SPORE_POD" },
                boss = "Core Behemoth", bossBody = "A Carapace that crawled into the reactor and grew. HP 320, front takes 15%. Phase 1 (100-65%): Fallout Walk: it walks the radiation ring and every cell it touches becomes q for 10 s; charges along a yellow lane (1.0 s) that ends in a radiation splash. Steam vents erupting under it crack its shell (front armour gone for 5 s and it staggers 1 s). Phase 2 (65-35%): Critical: it vents its back: three radiation rings (red, 1.2 s) pulse outward; it absorbs radiation, so every q cell within 3 m heals it 1 HP/s. The four valves (R) purge one quarter of the arena each (cooldown 20 s): purge the ring under it to stop the heal. Phase 3 (35-0%): Meltdown: a reactor fire FRONT sweeps from the north at 1.0 m/s and stops at the reactor block, cutting the arena in half; completing a valve pauses it 4 s. The boss enrages (speed 0.8x, charges every 4 s). Counterplay: lure charges into the reactor block (stun 3 s, back exposed), fight it on the vents, and turn valves in the gaps.", bossLook = "Carapace placeholder at 3.0x, lead grey #5f6670 shell with a glowing yellow-green core stripe #c8ff3a down the back and blue Cherenkov point light under its belly.",
                modifiers = new[] { "Hot Core: radiation fills 30% faster and decays 30% slower.", "Overpressure: all vents cycle in 4 s instead of 6 s.", "Containment Breach: every Drone leaves a 1-cell q trail for 3 s.", "Blackout: the plant's lights fail; DARKNESS rules with valves acting as light pylons once turned." },
                stars = new[] { "Clear the zone.", "No revive and under par (5:30).", "Kill the Core Behemoth while it stands in a steam eruption (killing blow inside a vent)." }, starBonus = "Clear without the RAD meter ever reaching 100%.", par = 330,
                layoutNotes = new Dictionary<string, string> { {"halvorsen-a", "Turbine Hall. Radiation patches in three quarters, a vent grid, the three valves in the north-west, east and south-west."}, {"halvorsen-b", "Spent Fuel Pool. The cooling pool (blue cells) at the north with a nest on it, irradiated corners holding the other two nests, Spore Pods at the pool edge."}, {"halvorsen-c", "Coolant Pumps. The pump on a railed dais in the middle, valves north and south, vents in a ring, radiation at the corners."}, {"halvorsen-d", "Core Scram. The reactor block at the north with four control rods around it, three inside radiation; the lift in the north-east corner."}, {"halvorsen-boss", "Core Chamber. Reactor block in the centre, radiation ring around it, vents at the cardinal points, valves in the four corners."} } },
            new SectorDef { id = "burrows", name = "THE BURROWS", num = 16, act = "IV", power = 7100, tier = 6, art = "hive", lat = -28.4f, lon = 99.6f, endless = false,
                blurb = "Below the reactor the swarm has dug a city", pitch = "Below the reactor the swarm has dug a city: pitch-black tunnels, egg-lined walls that breathe, and things that hunt by sound.", signature = "Act IV opens with a horror floor. You only see and shoot what is lit, so flares and pylons are your ammunition as much as bullets are: light a pylon and that cavern is yours. The tunnels are full of egg clusters you can't see until your light touches them, hive walls that can be shot open for a shortcut (and grow back), and nests that keep the dark full. Burrowers erupt from the floor, Stalkers come cloaked from behind and Ticks swarm out of egg fields, so the dash is always on your thumb.",
                unlockAny = new string[] { "meltdown" }, unlockAfter = "meltdown",
                floorTint = C(0x3b2f27), wallTint = C(0x4a3d33), accent = C(0x2a0f33), sun = C(0x9fb0c8), sunIntensity = 1.1f, ambient = C(0x1a1420), fog = C(0x050407), fogStart = 40.0f, fogEnd = 120.0f, particles = Particles.Ash,
                order = new[] { Game.Goal.Hunt, Game.Goal.Relay, Game.Goal.Assassinate, Game.Goal.Survive, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Hunt, spec = "HUNT", param = "3 nests", layout = "burrows/burrows-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 64), new EnemyEntry("Leaper", 8), new EnemyEntry("Burrower", 4), new EnemyEntry("Tick", 16), new EnemyEntry("Spore Pod", 2) }, events = "Teach. The warren. Two pylons and two flare caches on the main route. The first nest is visible from the start (glow), the other two are behind hive walls. Each nest killed lights its chamber (nest glow turns into a 6 m white light for the rest of the floor).", script = "[{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.1,\"area\":\"all\",\"dark\":true}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"LIGHT THE PYLONS. FLARES STICK TO ENEMIES.\"}},{\"when\":{\"done\":{\"kind\":\"nest\"}},\"do\":\"LIGHT\",\"params\":{\"level\":1.0,\"area\":\"nest chamber\",\"radius_m\":6}}]" },
                    new ZoneFloor { goal = Game.Goal.Relay, spec = "RELAY", param = "3 lamp-line relays, in order", layout = "burrows/burrows-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 66), new EnemyEntry("Leaper", 8), new EnemyEntry("Burrower", 4), new EnemyEntry("Stalker", 3), new EnemyEntry("Tick", 18), new EnemyEntry("Weaver", 2) }, events = "Twist. A long winding tunnel the colony miners lit with a lamp line. Each relay (R) relights one third of the tunnel permanently (lit cells: enemies there are exposed, +20% damage). Between relays, egg clusters along the walls hatch as you pass. Relay 2 is in the middle of a Stalker pair's patrol: the heartbeat audio starts before you see them.", script = "[{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.1,\"area\":\"all\",\"dark\":true}},{\"when\":{\"done\":{\"kind\":\"relay\"}},\"do\":\"LIGHT\",\"params\":{\"level\":1.0,\"area\":\"tunnel third of the completed relay\",\"exposed\":true}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":1}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Stalker\",\"count\":2,\"at\":\"ahead\",\"near\":\"R2\"}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":1}},\"do\":\"CUE\",\"params\":{\"id\":\"heartbeat\",\"delay\":0}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":2}},\"do\":\"LIGHT\",\"params\":{\"level\":0.1,\"area\":\"tunnel third 1\"}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":2}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Stalker\",\"count\":2,\"at\":\"behind\"}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":2}},\"do\":\"CUE\",\"params\":{\"id\":\"heartbeat_fast\"}},{\"when\":{\"done\":{\"kind\":\"relay\",\"index\":2}},\"do\":\"HINT\",\"params\":{\"text\":\"THE LAMPS BEHIND YOU ARE GOING OUT\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Assassinate, spec = "ASSASSINATE", param = "the Tunnel Matron", layout = "burrows/burrows-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 58), new EnemyEntry("Leaper", 6), new EnemyEntry("Burrower", 4), new EnemyEntry("Stalker", 2), new EnemyEntry("Tick", 16), new EnemyEntry("Mender", 2), new EnemyEntry("Tunnel Matron", 1) }, events = "Test. The Tunnel Matron (mini-boss) flees through the hive walls (she passes them; they open for her and close behind) toward the far side, summoning Burrower escorts every 10 s. Kill her in 60 s for the bonus. Flares stuck on her (a flare thrown within 1 m sticks) keep her visible.", script = "[{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.1,\"area\":\"all\",\"dark\":true}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"STICK A FLARE ON HER. 60 S FOR THE BONUS.\"}},{\"when\":{\"t\":20},\"do\":\"HATCH_ALL\",\"params\":{\"wobble\":2}},{\"when\":{\"t\":40},\"do\":\"HATCH_ALL\",\"params\":{\"wobble\":2}},{\"when\":{\"t\":17},\"do\":\"HINT\",\"params\":{\"text\":\"THE BROOD IS WAKING\"}},{\"when\":{\"start\":true},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"tunnel_matron\",\"count\":1,\"at\":\"far_S\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Survive, spec = "SURVIVE", param = "75 s", layout = "burrows/burrows-d", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 80), new EnemyEntry("Leaper", 10), new EnemyEntry("Burrower", 5), new EnemyEntry("Stalker", 3), new EnemyEntry("Tick", 22), new EnemyEntry("Splitter", 4), new EnemyEntry("Shrieker", 2) }, events = "Climax: the Deep Dark. Only two pylons and one flare cache. Every egg on the floor hatches at 30 s and again at 60 s (eggs regrow on creep cells). At 45 s the hero's own light flickers out for 6 s ('LIGHT FAILURE'): only flares and pylons see.", script = "[{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.1,\"area\":\"all\",\"dark\":true}},{\"when\":{\"t\":30},\"do\":\"HATCH_ALL\",\"params\":{\"wobble\":3}},{\"when\":{\"t\":30},\"do\":\"SET\",\"params\":{\"system\":\"EGGS\",\"regrow_s\":20}},{\"when\":{\"t\":45},\"do\":\"LIGHT\",\"params\":{\"level\":0,\"area\":\"hero\",\"for\":6}},{\"when\":{\"t\":45},\"do\":\"HINT\",\"params\":{\"text\":\"LIGHT FAILURE\"}},{\"when\":{\"t\":60},\"do\":\"HATCH_ALL\",\"params\":{\"wobble\":3}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "burrows/burrows-boss", enemies = new EnemyEntry[] { new EnemyEntry("The Gloom", 1), new EnemyEntry("Drone", 30), new EnemyEntry("Burrower", 3), new EnemyEntry("Tick", 14), new EnemyEntry("Stalker", 2) }, events = "The Gloom Pit: four pylons in the corners, a central dark ring (d cells stay unlit even with pylons), hive walls as cover.", script = "[{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.1,\"area\":\"all\",\"dark\":true}},{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"DARKNESS\",\"unlit_cells\":\"d\"}},{\"when\":{\"boss_hp\":0.35},\"do\":\"HATCH_ALL\",\"params\":{\"wobble\":3}}]" },
                },
                mechanics = new[] { "DARKNESS", "EGGS", "HIVE_WALL", "NEST", "INTERACT" },
                boss = "The Gloom", bossBody = "A Stalker grown to the size of a truck. HP 300. Phase 1 (100-65%): Hunt in the Dark: it stays cloaked and circles at 1.3x; it can only be targeted while inside light (pylons, flares, the hero's light) and takes +20% in pylon light. It strikes from behind: de-cloak hiss and a white blade arc (0.6 s), 28 damage. Phase 2 (65-35%): Lights Out: every 15 s it smashes the nearest lit pylon (a yellow line from it to the pylon, 1.5 s, interrupted by 6 RH of damage); the hero must relight pylons (1.5 s stand) under pressure. It digs through hive walls (they explode outward, 10 damage). Phase 3 (35-0%): Many Eyes: it splits into itself plus two shadow decoys (Shade Stalker rule), all three cloaked; only the real one has eye glints, and the eggs on the floor hatch all at once. Counterplay: stand in a lit pylon and let it come to you; a flare thrown on its de-cloak sticks and reveals it for 8 s; area damage reveals all three in phase 3.", bossLook = "Leaper model at 2.8x, near-black #141218 with the Stalker's cyan emissive slit #4fd2ff, cloaked = 12% alpha with the scrolling noise; decoys use the same at 8% alpha with no eye glints.",
                modifiers = new[] { "Pitch Black: no pylons on the first floor of each layout and flares start at 2.", "Ambush Burrows: +60% Burrowers and they surface twice per dig.", "Egg Carpet: every creep cell grows an egg cluster after 20 s.", "Stalker Pack: Stalkers come in pairs (the second de-cloaks 1 s after the first)." },
                stars = new[] { "Clear the zone.", "No revive and under par (6:00).", "Light every pylon on every floor, and kill the Tunnel Matron within 60 s." }, starBonus = "Destroy 40 egg clusters before they hatch in one run.", par = 360,
                layoutNotes = new Dictionary<string, string> { {"burrows-a", "Warren. Rock tunnels around three nest chambers, two pylons, two flare caches, hive walls hiding shortcuts."}, {"burrows-b", "Lamp Line. One long switchback tunnel from the north-west to the south-east, relays at each third, egg clusters along the walls."}, {"burrows-c", "Matron's Run. A cavern crossed by hive walls; the Matron starts north and flees south-east through the walls."}, {"burrows-d", "The Deep Dark. A wide cavern with egg fields everywhere, two pylons, one flare cache, dark pockets."}, {"burrows-boss", "Gloom Pit. Four pylons in the corners, a dark ring in the middle, hive walls and rock pillars as cover."} } },
            new SectorDef { id = "hive-core", name = "HIVE CORE", num = 17, act = "IV", power = 8300, tier = 6, art = "hive", lat = -34.5f, lon = -122.9f, endless = false,
                blurb = "The living centre of the infestation", pitch = "The living centre of the infestation: a cathedral of flesh where the floor grows back under your feet and the walls have a pulse.", signature = "Creep is the enemy here. It slows you 35% and heals and speeds the swarm, and on these floors it grows twice as fast as anywhere else. So you carve your own ground: dash lines scorch it, barrels and explosions burn holes in it, Incendiary rounds paint safe lanes. Nests are seeds, hive walls are seeds, and the heart pulse grows everything at once. Kill the seeds first and the floor recedes; ignore them and you fight knee-deep in it.",
                unlockAny = new string[] { "burrows" }, unlockAfter = "burrows",
                floorTint = C(0x2a0f33), wallTint = C(0x3d1f47), accent = C(0xb04dff), sun = C(0x7a3f9e), sunIntensity = 0.7f, ambient = C(0x2a1433), fog = C(0x1e0b26), fogStart = 40.0f, fogEnd = 120.0f, particles = Particles.Ash,
                order = new[] { Game.Goal.Burn, Game.Goal.Hunt, Game.Goal.Escort, Game.Goal.Uplink, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Burn, spec = "BURN", param = "scorch 80% of the creep", layout = "hive-core/core-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 70), new EnemyEntry("Leaper", 8), new EnemyEntry("Spitter", 6), new EnemyEntry("Tick", 18), new EnemyEntry("Spore Pod", 3) }, events = "Teach. Creep fields. A guaranteed Incendiary Rounds drop at 5 s with the hint 'SCORCH THE CREEP: DASH, EXPLODE, BURN'. Three nests keep regrowing it: the burn bar visibly stalls until they die. Barrels sit in the thickest fields.", script = "[{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"SPREAD\",\"skin\":\"creep\",\"tick\":1.25}},{\"when\":{\"every\":{\"s\":10}},\"do\":\"SEED\",\"params\":{\"skin\":\"creep\",\"at\":\"c\",\"count\":1,\"pulse\":true,\"regrow_hive_walls\":false}},{\"when\":{\"t\":5},\"do\":\"DROP\",\"params\":{\"kind\":\"incendiary_rounds\",\"at\":\"hero\"}},{\"when\":{\"t\":5},\"do\":\"HINT\",\"params\":{\"text\":\"SCORCH THE CREEP: DASH, EXPLODE, BURN\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Hunt, spec = "HUNT", param = "4 nests", layout = "hive-core/core-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 72), new EnemyEntry("Leaper", 8), new EnemyEntry("Carapace", 3), new EnemyEntry("Mender", 2), new EnemyEntry("Spore Pod", 4), new EnemyEntry("Tick", 18) }, events = "Twist. Ventricles: each nest is sealed in a chamber behind hive walls (one from the hub side, one from the outer side). Shooting a wall open starts its 12 s regrow clock, so you hold the gap or get sealed in with the nest's spawns. Carapace charges break hive walls (and Carapaces are drawn to block gaps).", script = "[{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"SPREAD\",\"skin\":\"creep\",\"tick\":1.25}},{\"when\":{\"every\":{\"s\":10}},\"do\":\"SEED\",\"params\":{\"skin\":\"creep\",\"at\":\"c\",\"count\":1,\"pulse\":true,\"regrow_hive_walls\":false}},{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"HIVE_WALL\",\"carapace_charge_breaks\":true}}]" },
                    new ZoneFloor { goal = Game.Goal.Escort, spec = "ESCORT", param = "the Torch cart", layout = "hive-core/core-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 76), new EnemyEntry("Leaper", 8), new EnemyEntry("Splitter", 4), new EnemyEntry("Shrieker", 2), new EnemyEntry("Weaver", 2), new EnemyEntry("Tick", 20), new EnemyEntry("The Gardener", 1) }, events = "Test. The Torch is a flamethrower cart that scorches a 2-cell lane as it rolls, but stops on creep (it only moves on scorched or bare floor). Burn the track ahead of it, keep enemies off it. The Gardener (mini-boss) appears at 40% and re-creeps the track ahead.", script = "[{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"SPREAD\",\"skin\":\"creep\",\"tick\":1.25}},{\"when\":{\"every\":{\"s\":10}},\"do\":\"SEED\",\"params\":{\"skin\":\"creep\",\"at\":\"c\",\"count\":1,\"pulse\":true,\"regrow_hive_walls\":false}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"THE TORCH STOPS ON CREEP. BURN THE TRACK AHEAD.\"}},{\"when\":{\"progress\":0.4},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"The Gardener\",\"count\":1,\"at\":\"ahead\",\"target\":\"track\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Uplink, spec = "UPLINK", param = "ring hops across 5 chambers, 30 s", layout = "hive-core/core-d", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 84), new EnemyEntry("Leaper", 10), new EnemyEntry("Bloater", 4), new EnemyEntry("Splitter", 4), new EnemyEntry("Lancer", 2), new EnemyEntry("Tick", 22), new EnemyEntry("Stalker", 2) }, events = "Climax. Each ring sits on creep: scorch the ring before standing in it, or hold it at -35% speed. The heart pulse every 10 s regrows every hive wall on the floor and adds a creep tick everywhere. Acid pools line the routes between chambers.", script = "[{\"when\":{\"start\":true},\"do\":\"SET\",\"params\":{\"system\":\"SPREAD\",\"skin\":\"creep\",\"tick\":1.25}},{\"when\":{\"every\":{\"s\":10}},\"do\":\"SEED\",\"params\":{\"skin\":\"creep\",\"at\":\"c\",\"count\":1,\"pulse\":true,\"regrow_hive_walls\":true}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "hive-core/core-boss", enemies = new EnemyEntry[] { new EnemyEntry("The Overmind", 1), new EnemyEntry("Drone", 32), new EnemyEntry("Mender", 4), new EnemyEntry("Leaper", 4), new EnemyEntry("Tick", 12) }, events = "The Hive Heart. The Overmind floats in a chamber inside a heart built of rib blocks; four Psionic Nodes are nests in the corners; acid pools ring the heart.", script = "[{\"when\":{\"every\":{\"s\":10}},\"do\":\"SEED\",\"params\":{\"skin\":\"creep\",\"at\":\"c\",\"count\":1,\"pulse\":true,\"regrow_hive_walls\":false}},{\"when\":{\"boss_hp\":0.5},\"do\":\"SEED\",\"params\":{\"skin\":\"creep\",\"at\":\"@\",\"tick\":5}},{\"when\":{\"boss_hp\":0.5},\"do\":\"SET\",\"params\":{\"system\":\"ACID_POOL\",\"grow_cells\":1,\"every_s\":10}}]" },
                },
                mechanics = new[] { "SPREAD", "HIVE_WALL", "NEST", "ACID_POOL" },
                boss = "The Overmind, enthroned in the Hive Heart", bossBody = "HP 400, stationary, floating above a heart built from rib blocks. Phase 1 (Shielded): the shield holds while any of the 4 Psionic Nodes (the corner nests, 30 RH, each tethered by a Mender) lives. Systole every 10 s: the heart contracts and a ring of creep bursts out (2 cells), plus Mind Lash (a rotating red line, 1.0 s preview, 15 damage) every 8 s. Phase 2 (100-50%): Puppet (3 enemies crowned and frenzied until it takes 40 damage) and Psychic Mirror (2 purple clones of the hero). Systole now also regrows hive walls inside the heart's mouth, sealing it: shoot or blast them to keep a firing line. Phase 3 (50-0%): Hive Bloom: 2 nodes regrow, creep spreads from the heart every 5 s and the acid pools spill (each pool grows 1 cell per 10 s). Counterplay: kill nodes in order of the Mender tethers, scorch a lane from the heart's mouth to a node, and save explosions for the walls inside the mouth.", bossLook = "Bloater at 2.0x, pink-grey brain tint #c58a9a with violet veins, bobbing 1.5 m above a pedestal; the heart is a ring of rib blocks (tall B blocks, creep material) that scale 1.0-1.08 on each Systole with a violet point light inside; shield = Bulwark bubble at 4 m in violet.",
                modifiers = new[] { "Overgrowth: creep ticks twice as fast and the cap rises to 60% of the floor.", "Fortified Hive: hive walls take 15 RH and regrow in 8 s.", "Acid Seep: every nest is ringed by acid cells.", "Hive-linked Swarm: 20% of spawns are Hive-linked (enemies doc modifier)." },
                stars = new[] { "Clear the zone.", "No revive and under par (6:00).", "Destroy every nest on every floor before it spawns a third Drone, and win the boss with the Overmind's shield down in under 30 s." }, starBonus = "Scorch 500 creep cells in one run.", par = 360,
                layoutNotes = new Dictionary<string, string> { {"core-a", "Creep Fields. Open ground under thick creep, three nests, acid pools, barrels in the densest fields."}, {"core-b", "Ventricles. Four corner chambers sealed by hive walls around a central hub; acid in the hub."}, {"core-c", "Torch Run. The cart track runs from the south-west up through the middle to the north-east, crossing every creep field."}, {"core-d", "Pulse Chambers. Five ring spots: four in creep chambers and one in the heart-like centre around a nest."}, {"core-boss", "Hive Heart. The heart of rib blocks in the centre with its mouth to the south, the Overmind inside, four nests in the corners, acid pools around the heart."} } },
            new SectorDef { id = "brood-spire", name = "BROODMOTHER'S SPIRE", num = 18, act = "IV", power = 9750, tier = 6, art = "hive", lat = -41.3f, lon = 14.6f, endless = false,
                blurb = "A kilometre-tall tower of chitin grown out of the hive, with the Broodmother at the top", pitch = "A kilometre-tall tower of chitin grown out of the hive, with the Broodmother at the top: every mechanic you have learned, in the order that hurts most, and then her.", signature = "The final exam, curated. Each floor puts two or three of the mechanics you've already mastered against each other: creep that slows you next to pits that kill the swarm, crumbling walkways that close routes while a creep tide chases you, hive walls that hide eggs, vents and spore pods guarding the beacon. Every floor ends higher up the spire, and the boss fight ends the game with the floor itself falling away.",
                unlockAny = new string[] { "hive-core" }, unlockAfter = "hive-core",
                floorTint = C(0x2b2230), wallTint = C(0x3d2c45), accent = C(0xd8cbb8), sun = C(0xffb070), sunIntensity = 1.0f, ambient = C(0x3a2540), fog = C(0x6b3a4a), fogStart = 25.0f, fogEnd = 60.0f, particles = Particles.Ash,
                order = new[] { Game.Goal.Purge, Game.Goal.Salvage, Game.Goal.Defend, Game.Goal.Detonate, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Purge, spec = "PURGE", param = "3 waves", layout = "brood-spire/brood-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 78), new EnemyEntry("Leaper", 10), new EnemyEntry("Shrieker", 2), new EnemyEntry("Spitter", 6), new EnemyEntry("Tick", 20), new EnemyEntry("Carapace", 3), new EnemyEntry("Spore Pod", 2) }, events = "Teach (it's a reminder). The Root Gate: creep, hive walls, egg clusters, pits on the west edge and vents in the lower deck. Every wave includes an elite with 2 modifiers. Wave 3 is led by a Warcry Shrieker.", script = "[{\"when\":{\"wave\":{\"n\":1,\"at\":\"start\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Carapace\",\"count\":1,\"elite\":true,\"modifiers\":2,\"at\":\"far_S\"}},{\"when\":{\"wave\":{\"n\":2,\"at\":\"start\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Leaper\",\"count\":1,\"elite\":true,\"modifiers\":2,\"at\":\"far_S\"}},{\"when\":{\"wave\":{\"n\":3,\"at\":\"start\"}},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Shrieker\",\"count\":1,\"elite\":true,\"variant\":\"Warcry Shrieker\",\"modifiers\":2,\"at\":\"far_S\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Salvage, spec = "SALVAGE", param = "5 black boxes from the first strike team", layout = "brood-spire/brood-b", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 80), new EnemyEntry("Leaper", 10), new EnemyEntry("Stalker", 3), new EnemyEntry("Weaver", 2), new EnemyEntry("Burrower", 4), new EnemyEntry("Tick", 22), new EnemyEntry("Bloater", 3) }, events = "Twist. The first strike team didn't make it: their recorders ($) lie in dark pockets, hive-walled nooks and beside a crumbling ledge. Each pickup plays a 3 s radio line from the dead squad (the story beat of the act) and triggers its ambush. The lift is at the south-west, past a pit bridge that crumbles.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"RECOVER THE FIRST STRIKE TEAM'S BLACK BOXES\"}},{\"when\":{\"done\":{\"kind\":\"pickup\"}},\"do\":\"CUE\",\"params\":{\"id\":\"dead_squad_radio\",\"length_s\":3,\"sequence\":true}}]" },
                    new ZoneFloor { goal = Game.Goal.Defend, spec = "DEFEND", param = "orbital beacon, 60 s", layout = "brood-spire/brood-c", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 88), new EnemyEntry("Leaper", 10), new EnemyEntry("Carapace", 4), new EnemyEntry("Lancer", 3), new EnemyEntry("Mender", 2), new EnemyEntry("Splitter", 4), new EnemyEntry("Tick", 22), new EnemyEntry("The Choir", 1) }, events = "Test. Plant the orbital beacon (G) on the ridge between two chasms and keep it alive for 60 s. Enemies come over crumbling bridges from both sides (shove and void kills), Lancers fire across the chasms. The Choir (mini-boss) arrives at 25 s.", script = "[{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"SHOVE THEM OFF THE BRIDGES\"}},{\"when\":{\"t\":25},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"The Choir\",\"count\":1,\"at\":\"far_S\"}}]" },
                    new ZoneFloor { goal = Game.Goal.Detonate, spec = "DETONATE", param = "4 spinal-node charges, then 25 s to the lift", layout = "brood-spire/brood-d", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 92), new EnemyEntry("Leaper", 12), new EnemyEntry("Burrower", 4), new EnemyEntry("Shrieker", 2), new EnemyEntry("Spitter", 6), new EnemyEntry("Weaver", 2), new EnemyEntry("Tick", 24) }, events = "Climax. Blow the spire's spine so it can't regrow: plant the four charges (!), two of them across pit belts on crumbling walkways. On the last plant the 25 s countdown starts AND a creep tide (FRONT, creep skin, 1.4 m/s) surges from the south behind you: the lift is at the top, across the last crumbling walkway. The explosion shakes the whole spire and leads straight into the boss intro.", script = "[{\"when\":{\"done\":{\"kind\":\"charge\",\"count\":4}},\"do\":\"FRONT\",\"params\":{\"skin\":\"creep\",\"dir\":\"N\",\"speed\":1.4,\"countdown\":0,\"state\":\"start\",\"from\":\"S wall\"}},{\"when\":{\"done\":{\"kind\":\"charge\",\"count\":4}},\"do\":\"CUE\",\"params\":{\"id\":\"spire_spine_blast\",\"shake\":0.3}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "", layout = "brood-spire/brood-boss", enemies = new EnemyEntry[] { new EnemyEntry("Broodmother Ascendant", 1), new EnemyEntry("Drone", 40), new EnemyEntry("Leaper", 6), new EnemyEntry("Spitter", 4), new EnemyEntry("Tick", 16) }, events = "The Crown of the Spire: an inner arena (egg sacs, pillars, the jump pad) inside a ring of crumbling chitin, an outer ring with the med stations, and the lift at the south edge for the escape after she falls.", script = "[{\"when\":{\"boss_hp\":0.25},\"do\":\"SET\",\"params\":{\"system\":\"COLLAPSE\",\"collapse\":\"k\",\"over_s\":4,\"order\":\"outward from @\"}},{\"when\":{\"boss_hp\":0.25},\"do\":\"SEED\",\"params\":{\"skin\":\"creep\",\"at\":\"@\",\"tick\":2,\"cap_per_tick\":3}},{\"when\":{\"boss_hp\":0.1},\"do\":\"CLOSE\",\"params\":{\"target\":\"J\"}},{\"when\":{\"boss_hp\":0.0},\"do\":\"FRONT\",\"params\":{\"skin\":\"creep\",\"dir\":\"S\",\"speed\":1.2,\"countdown\":0,\"state\":\"start\",\"damage\":0,\"duration_s\":15}},{\"when\":{\"boss_hp\":0.0},\"do\":\"OPEN\",\"params\":{\"target\":\"L\"}}]" },
                },
                mechanics = new[] { "SPREAD", "PIT", "COLLAPSE", "FRONT", "DARKNESS", "EGGS", "HIVE_WALL", "INTERACT", "JUMP_PAD", "SPORE_POD", "VENT" },
                boss = "Broodmother Ascendant", bossBody = "HP 480, size 3.6 m. Phases 1-3 are the enemies doc fight at final-zone strength: Brood (clutches every 5 s, Tail Sweep, egg sacs hatch Ticks), Acid Rain (Acid Barrage, pillars block it) and Swarm Call (she burrows for 8 s while two waves pour in, then erupts under the hero). Zone rule throughout: every slam of hers cracks the nearest crumbling chitin cell, and enemies shoved off the ring fall. Phase 4 (25-0%): The Spire Falls. She tears the crown loose: the whole crumbling ring around the inner arena falls into the void over 4 s (cell by cell, outward from her), so the fight is on the inner island; the jump pad is the only link to the outer ring and the med stations. Creep pours from her abdomen (one tick every 2 s around her, 3-cell cap per tick), clutches every 3 s. Ledge Teeter: when an explosion, a Barrage knockback or her own Tail Sweep miss pushes her within 1 m of the island lip, she teeters for 3 s and takes double damage (once per 12 s). At 10% she makes a final leap to the outer ring through the jump pad (she's too big; the pad breaks) and the last 10% is fought on the outer ring with the void between you. On death: the spire breaks, a 15 s OUTRUN to the lift with the creep FRONT behind you (no damage unless you stop: the victory lap), and the credits roll from the lift.", bossLook = "Bloater at 3.0x, deep violet #4b1f5c with a 1.8x stretched abdomen, crown of Lancer spikes x6 in bone white, violet emissive veins; phase 4 adds a cracked orange-amber glow #ffb070 in her seams (the dusk light coming through).",
                modifiers = new[] { "Final Tide: every floor has a slow creep FRONT (0.6 m/s) from the south.", "Royal Guard: every elite has 3 modifiers.", "Crumbling Spire: every walkway cell next to a pit is a crumbling cell.", "Endless Brood: nests on every floor respawn 20 s after death." },
                stars = new[] { "Clear the zone.", "No revive and under par (7:00).", "Defeat the Broodmother Ascendant without leaving the inner island in phase 4 (no jump pad)." }, starBonus = "Finish the DETONATE floor with the creep tide never touching you.", par = 420,
                layoutNotes = new Dictionary<string, string> { {"spire-a", "Root Gate. Creep and hive walls at the north gate, pit edges on the west, egg clusters, two Spore Pods, vents on the lower deck."}, {"spire-b", "Fallen Squad. Five recorders in pockets (dark nooks, hive-walled rooms), the lift at the south-west past crumbling pit bridges."}, {"spire-c", "Beacon Ridge. The beacon on a ridge between two chasms, crumbling bridges north and south, a permanent centre crossing."}, {"spire-d", "The Spine. Pit belts with crumbling crossings, four spinal nodes, the lift at the top north-west."}, {"spire-boss", "Crown of the Spire. Inner arena (egg sacs, pillars, jump pad) inside a crumbling ring, outer ring with two med stations and the lift at the south edge."} } },
            new SectorDef { id = "swarm-gate", name = "SWARM GATE (ENDLESS)", num = 0, act = "-", power = 0, tier = 1, art = "drowned", lat = -30.0f, lon = 160.0f, endless = true,
                blurb = "Endless Breach", pitch = "Endless Breach: the swarm's own gate, and every floor of every zone you have cleared stitched into one descent that only ends when you do.", signature = "The replay engine. Each floor pulls a random layout (and its mechanics) from every zone the player has cleared, plus the two gate layouts, with an objective chosen from that layout's markers. Power climbs every floor, every 5th floor is a boss from the boss pool, and between floors you pick one of three Gate Boons (a run-long upgrade) or keep your health. The mechanics list above is only for the gate's own layouts (they borrow creep, gusts, dark pockets and pits); everything else comes from the source zones.",
                unlockAny = new string[] { "seismic-mine" }, unlockAfter = "seismic-mine",
                floorTint = C(0x121018), wallTint = C(0x24202c), accent = C(0x9fe6ff), sun = C(0xd9ccff), sunIntensity = 0.9f, ambient = C(0x2a2433), fog = C(0x1a1424), fogStart = 20.0f, fogEnd = 55.0f, particles = Particles.None,
                order = new[] { Game.Goal.Purge, Game.Goal.Uplink, Game.Goal.Survive, Game.Goal.Relay, Game.Goal.Boss },
                floors = new ZoneFloor[] {
                    new ZoneFloor { goal = Game.Goal.Purge, spec = "PURGE", param = "cycle floor 1 (floors 1, 6, 11 ...)", layout = "swarm-gate/gate-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 50), new EnemyEntry("Leaper", 6), new EnemyEntry("Tick", 10), new EnemyEntry("Spitter", 4) }, events = "Opening floor of each 5-floor cycle. Floor 1 of the run is always the Gate Antechamber; later cycle-openers pull a random cleared zone's floor-1 layout. Enemy budget: zone-1 budget x (1 + 0.12 x (floor - 1)), elite chance +1% per floor, modifier slots +1 every 10 floors.", script = "[{\"when\":{\"start\":true},\"do\":\"CUE\",\"params\":{\"id\":\"gate_floor_counter\",\"for\":2}},{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":2,\"radius\":2,\"interval\":12,\"skin\":\"lightning\",\"min_floor\":6}},{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"dir\":\"random\",\"period\":15,\"min_floor\":16}},{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.45,\"area\":\"all\",\"min_floor\":21}},{\"when\":{\"start\":true},\"do\":\"FOG\",\"params\":{\"end_m\":28,\"density_mult\":1.6,\"min_floor\":21}},{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"ACID_RAIN\",\"state\":\"on\",\"period\":25,\"min_floor\":26}},{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.1,\"area\":\"all\",\"dark\":true,\"min_floor\":31}},{\"when\":{\"every\":{\"s\":20}},\"do\":\"DROP\",\"params\":{\"kind\":\"flare\",\"at\":\"random\",\"min_floor\":31}},{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":3,\"radius\":2,\"interval\":9,\"skin\":\"rock\",\"leaves\":\"rubble\",\"min_floor\":36}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"GATE DEPTH {floor}: {stage_name}\",\"only_if\":\"first floor of a new stage\"}},{\"when\":{\"start\":true},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Spore Pod\",\"count\":3,\"at\":\"random\",\"group\":\"spread\",\"min_floor\":11}}]" },
                    new ZoneFloor { goal = Game.Goal.Uplink, spec = "UPLINK", param = "cycle floor 2: random objective the layout supports", layout = "swarm-gate/gate-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 54), new EnemyEntry("Leaper", 6), new EnemyEntry("Carapace", 2), new EnemyEntry("Weaver", 2), new EnemyEntry("Tick", 12) }, events = "A random layout from any cleared zone; the objective is picked from what its markers allow (HOLD/UPLINK on Z, RELAY on R, HUNT on n, SALVAGE on $, DEFEND on G, ESCORT on Q, DETONATE on !), never the same objective twice in a row. Shown here on the gate antechamber's three rings.", script = "[{\"when\":{\"start\":true},\"do\":\"CUE\",\"params\":{\"id\":\"gate_floor_counter\",\"for\":2}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"UPLINK: FOLLOW THE RING\"}},{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":2,\"radius\":2,\"interval\":12,\"skin\":\"lightning\",\"min_floor\":6}},{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"dir\":\"random\",\"period\":15,\"min_floor\":16}},{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.45,\"area\":\"all\",\"min_floor\":21}},{\"when\":{\"start\":true},\"do\":\"FOG\",\"params\":{\"end_m\":28,\"density_mult\":1.6,\"min_floor\":21}},{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"ACID_RAIN\",\"state\":\"on\",\"period\":25,\"min_floor\":26}},{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.1,\"area\":\"all\",\"dark\":true,\"min_floor\":31}},{\"when\":{\"every\":{\"s\":20}},\"do\":\"DROP\",\"params\":{\"kind\":\"flare\",\"at\":\"random\",\"min_floor\":31}},{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":3,\"radius\":2,\"interval\":9,\"skin\":\"rock\",\"leaves\":\"rubble\",\"min_floor\":36}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"GATE DEPTH {floor}: {stage_name}\",\"only_if\":\"first floor of a new stage\"}},{\"when\":{\"start\":true},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Spore Pod\",\"count\":3,\"at\":\"random\",\"group\":\"spread\",\"min_floor\":11}}]" },
                    new ZoneFloor { goal = Game.Goal.Survive, spec = "SURVIVE", param = "cycle floor 3: 45 s + 3 s per cycle", layout = "swarm-gate/gate-arena", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 60), new EnemyEntry("Leaper", 8), new EnemyEntry("Splitter", 4), new EnemyEntry("Shrieker", 2), new EnemyEntry("Tick", 14) }, events = "A pressure floor on the gauntlet arena or a random SURVIVE-capable layout. From floor 13 on, a mini-boss from the pool (Gale Ravager, Deck Crusher, Hot Gravid, Tunnel Matron, The Gardener, The Choir, and Act I-II mini-bosses) arrives at the midpoint.", script = "[{\"when\":{\"start\":true},\"do\":\"CUE\",\"params\":{\"id\":\"gate_floor_counter\",\"for\":2}},{\"when\":{\"progress\":0.5},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"pool_miniboss\",\"count\":1,\"at\":\"far_S\",\"min_floor\":13}},{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":2,\"radius\":2,\"interval\":12,\"skin\":\"lightning\",\"min_floor\":6}},{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"dir\":\"random\",\"period\":15,\"min_floor\":16}},{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.45,\"area\":\"all\",\"min_floor\":21}},{\"when\":{\"start\":true},\"do\":\"FOG\",\"params\":{\"end_m\":28,\"density_mult\":1.6,\"min_floor\":21}},{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"ACID_RAIN\",\"state\":\"on\",\"period\":25,\"min_floor\":26}},{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.1,\"area\":\"all\",\"dark\":true,\"min_floor\":31}},{\"when\":{\"every\":{\"s\":20}},\"do\":\"DROP\",\"params\":{\"kind\":\"flare\",\"at\":\"random\",\"min_floor\":31}},{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":3,\"radius\":2,\"interval\":9,\"skin\":\"rock\",\"leaves\":\"rubble\",\"min_floor\":36}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"GATE DEPTH {floor}: {stage_name}\",\"only_if\":\"first floor of a new stage\"}},{\"when\":{\"start\":true},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Spore Pod\",\"count\":3,\"at\":\"random\",\"group\":\"spread\",\"min_floor\":11}}]" },
                    new ZoneFloor { goal = Game.Goal.Relay, spec = "RELAY", param = "cycle floor 4: random objective, plus a Gate Mutator", layout = "swarm-gate/gate-a", enemies = new EnemyEntry[] { new EnemyEntry("Drone", 62), new EnemyEntry("Leaper", 8), new EnemyEntry("Lancer", 2), new EnemyEntry("Mender", 2), new EnemyEntry("Stalker", 2), new EnemyEntry("Tick", 14) }, events = "A random layout and objective as on cycle floor 2, plus one mutator from the upgrade doc pool (9.3) for this floor only, shown on a slot-machine banner. Clearing it pays double Alloy.", script = "[{\"when\":{\"start\":true},\"do\":\"CUE\",\"params\":{\"id\":\"gate_floor_counter\",\"for\":2}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"GATE MUTATOR\",\"banner\":\"slot_machine\",\"pool\":\"upgrade-system 9.3\"}},{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":2,\"radius\":2,\"interval\":12,\"skin\":\"lightning\",\"min_floor\":6}},{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"WIND\",\"state\":\"on\",\"dir\":\"random\",\"period\":15,\"min_floor\":16}},{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.45,\"area\":\"all\",\"min_floor\":21}},{\"when\":{\"start\":true},\"do\":\"FOG\",\"params\":{\"end_m\":28,\"density_mult\":1.6,\"min_floor\":21}},{\"when\":{\"start\":true},\"do\":\"WEATHER\",\"params\":{\"system\":\"ACID_RAIN\",\"state\":\"on\",\"period\":25,\"min_floor\":26}},{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0.1,\"area\":\"all\",\"dark\":true,\"min_floor\":31}},{\"when\":{\"every\":{\"s\":20}},\"do\":\"DROP\",\"params\":{\"kind\":\"flare\",\"at\":\"random\",\"min_floor\":31}},{\"when\":{\"start\":true},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":3,\"radius\":2,\"interval\":9,\"skin\":\"rock\",\"leaves\":\"rubble\",\"min_floor\":36}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"GATE DEPTH {floor}: {stage_name}\",\"only_if\":\"first floor of a new stage\"}},{\"when\":{\"start\":true},\"do\":\"SPAWN\",\"params\":{\"enemy\":\"Spore Pod\",\"count\":3,\"at\":\"random\",\"group\":\"spread\",\"min_floor\":11}}]" },
                    new ZoneFloor { goal = Game.Goal.Boss, spec = "BOSS", param = "cycle floor 5: boss drawn from boss_pool (floors 5, 10, 15 ...); the table shows floor 5's guaranteed draw", layout = "swarm-gate/gate-arena", enemies = new EnemyEntry[] { new EnemyEntry("Gravid Bloater", 1), new EnemyEntry("Drone", 24), new EnemyEntry("Leaper", 4), new EnemyEntry("Tick", 10) }, events = "A boss from the pool, fought in its own zone's boss layout or in the gauntlet arena. No repeats until the pool is exhausted. Every 25th floor the boss is doubled (two from the pool at 60% HP each).", script = "[{\"when\":{\"start\":true},\"do\":\"CUE\",\"params\":{\"id\":\"gate_boss_silence\",\"for\":1}},{\"when\":{\"start\":true},\"do\":\"HINT\",\"params\":{\"text\":\"BOSS FLOOR\",\"boss\":\"drawn from boss_pool\"}},{\"when\":{\"start\":true},\"do\":\"LIGHT\",\"params\":{\"level\":0,\"area\":\"all\",\"flash\":1.0,\"floors\":[25,45]}},{\"when\":{\"boss_hp\":0.25},\"do\":\"FRONT\",\"params\":{\"skin\":\"collapse\",\"dir\":\"S\",\"from\":\"@\",\"speed\":0.8,\"countdown\":2,\"state\":\"start\",\"every_floor\":10}},{\"when\":{\"boss_hp\":0.25},\"do\":\"HINT\",\"params\":{\"text\":\"THE GATE IS FALLING\",\"every_floor\":10}},{\"when\":{\"boss_hp\":0.25},\"do\":\"CUE\",\"params\":{\"id\":\"gate_collapse\",\"every_floor\":10}},{\"when\":{\"boss_hp\":0.5},\"do\":\"STRIKE\",\"params\":{\"mode\":\"random\",\"count\":6,\"radius\":2,\"interval\":3,\"skin\":\"fire\",\"aim\":\"edge\",\"for\":12,\"floors\":[15,35,55]}}]" },
                },
                mechanics = new[] { "SPREAD", "WIND", "DARKNESS", "PIT", "INTERACT", "VENT" },
                boss = "Boss pool", bossBody = "Every boss the player has beaten: Gravid Bloater and the Act I-II bosses, Cloudbreaker, Fallen Vanguard, Core Behemoth, The Gloom, The Overmind, Broodmother Ascendant, and the enemies-doc bosses (Broodmother, The Maw). Boss HP scales with floor power; from floor 30 each boss gains its elite rule (one modifier) and from floor 50 two. Mechanics a boss needs that the gauntlet arena lacks are swapped for its home boss layout. Beating a boss floor offers an Epic card choice and a guaranteed power-up chest.", bossLook = "Each boss keeps its home look plus a cyan gate rim light and the floor number on its banner.",
